function applyCustomerTimesheetApiRecord(employeeId, periodKey, data) {
  const row = data && data.customer_timesheet;
  if (!row) return null;

  const record = recordFor(Number(employeeId), periodKey);
  const documentRecord = customerTimesheetFor(record);
  const assignmentId = Number(data && data.assignment_id || row.assignment_id || 0);
  const downloadUrl = String(row.download_url || "").trim();

  documentRecord.status = String(row.status || documentRecord.status || "missing");
  documentRecord.isExample = false;
  documentRecord.fileName = String(row.original_file_name || row.stored_file_name || "");
  documentRecord.originalFileName = String(row.original_file_name || "");
  documentRecord.fileData = downloadUrl || (String(row.storage_key || "").trim()
    ? WRITE_CUSTOMER_TIMESHEET_PATH + "?action=download&period=" + encodeURIComponent(periodKey) + "&employee_id=" + encodeURIComponent(String(employeeId)) + (assignmentId > 0 ? "&assignment_id=" + encodeURIComponent(String(assignmentId)) : "")
    : "");
  documentRecord.mimeType = String(row.mime_type || "application/pdf");
  documentRecord.uploadedAt = String(row.uploaded_at || "");
  documentRecord.uploadedBy = row.uploaded_by ? "Gebruiker #" + String(row.uploaded_by) : "";
  documentRecord.reviewedAt = String(row.reviewed_at || "");
  documentRecord.reviewedBy = row.reviewed_by ? "Gebruiker #" + String(row.reviewed_by) : "";
  documentRecord.reviewNote = String(row.review_note || "");
  documentRecord.sentAt = String(row.sent_to_broker_at || "");

  if (documentRecord.status !== "skipped") {
    documentRecord.skippedReason = "";
    documentRecord.skippedAt = "";
    documentRecord.skippedBy = "";
  }

  return documentRecord;
}

function applyMissingCustomerTimesheetApiRecord(employeeId, periodKey) {
  const record = recordFor(Number(employeeId), periodKey);
  record.customerTimesheet = blankCustomerTimesheet();
  return record.customerTimesheet;
}

function writeCustomerTimesheetToApi(action, options = {}) {
  const employeeId = Number(options.employeeId || currentEmployee().id);
  const periodKey = String(options.periodKey || currentPeriod().key);
  const assignmentId = Number(options.assignmentId || 0);
  const reviewNote = String(options.reviewNote || "").trim();
  const subject = String(options.subject || "").trim();
  const body = String(options.body || "").trim();
  const file = options.file || null;
  const mutationKey = periodKey + ":" + employeeId;
  readApiRuntime.customerTimesheetMutationEpochByKey[mutationKey] = Number(readApiRuntime.customerTimesheetMutationEpochByKey[mutationKey] || 0) + 1;

  return requestAuthCsrf()
    .then(token => {
      const formData = new FormData();
      formData.append("action", action);
      formData.append("period", periodKey);
      formData.append("employee_id", String(employeeId));
      if (assignmentId > 0) {
        formData.append("assignment_id", String(assignmentId));
      }
      if (reviewNote) {
        formData.append("review_note", reviewNote);
      }
      if (subject) formData.append("subject", subject);
      if (body) formData.append("body", body);
      if (file) {
        formData.append("file", file, file.name || "klanturenstaat");
      }

      return fetch(WRITE_CUSTOMER_TIMESHEET_PATH, {
        method: "POST",
        headers: { "Accept": "application/json", "X-CSRF-Token": token },
        body: formData
      });
    })
    .then(resp => resp.json().catch(() => ({})).then(data => ({ ok: resp.ok, data })))
    .then(result => {
      if (!result.ok || !result.data || result.data.ok !== true) {
        const message = String(result && result.data && result.data.message || "Klanturenstaatactie op server mislukt.");
        throw new Error(message);
      }
      readApiRuntime.customerTimesheetMutationEpochByKey[mutationKey] = Number(readApiRuntime.customerTimesheetMutationEpochByKey[mutationKey] || 0) + 1;
      applyCustomerTimesheetApiRecord(employeeId, periodKey, result.data);
      readApiRuntime.lastCustomerTimesheetsByPeriod[mutationKey] = Date.now();
      return result.data;
    });
}

function scheduleDraftTimesheetWrite() {
  if (!API_ENABLED || authRuntime.mode !== "auth" || state.currentRole !== "employee") return;
  if (writeRuntime.submitInFlight) return;
  const payload = buildTimesheetWritePayload("save_draft");
  const signature = JSON.stringify(payload);
  if (signature === writeRuntime.lastDraftSignature) return;

  if (writeRuntime.draftInFlight) {
    writeRuntime.pendingDraftSignature = signature;
    return;
  }

  if (writeRuntime.draftTimer) window.clearTimeout(writeRuntime.draftTimer);
  writeRuntime.draftTimer = window.setTimeout(() => {
    writeRuntime.draftTimer = null;
    writeRuntime.draftInFlight = true;
    writeRuntime.pendingDraftSignature = "";
    writeRuntime.draftPromise = writeTimesheetToApi("save_draft").then(() => {
      writeRuntime.lastDraftSignature = signature;
      const autosaveStatus = document.querySelector("#hours-autosave-status");
      if (autosaveStatus) autosaveStatus.textContent = "Gesynchroniseerd met server om " + new Intl.DateTimeFormat("nl-NL", { hour: "2-digit", minute: "2-digit" }).format(new Date());
    }).catch(error => {
      writeRuntime.lastDraftSignature = "";
      const now = Date.now();
      const message = String(error && error.message || "");
      if (now - writeRuntime.lastDraftErrorAt > 4000) {
        toast(message || "Concept kon niet op de server worden opgeslagen. Controleer je sessie en probeer opnieuw.");
        writeRuntime.lastDraftErrorAt = now;
      }
      const autosaveStatus = document.querySelector("#hours-autosave-status");
      if (autosaveStatus) autosaveStatus.textContent = message ? "Niet gesynchroniseerd: " + message : "Niet gesynchroniseerd met server.";
      console.warn("Draft save via write API failed", error);
    }).finally(() => {
      writeRuntime.draftInFlight = false;
      writeRuntime.draftPromise = null;
      if (!writeRuntime.submitInFlight && writeRuntime.pendingDraftSignature && writeRuntime.pendingDraftSignature !== writeRuntime.lastDraftSignature) {
        scheduleDraftTimesheetWrite();
      }
    });
  }, 700);
}

function initializeAuthSession() {
  applyAuthUiMode("checking");
  return requestAuthCsrf()
    .catch(() => null)
    .then(() => requestAuthMe())
    .then(data => {
      authRuntime.checked = true;
      authRuntime.available = true;
      applyAuthUiMode("auth");
      prefillAuthCredentialsFromSelection("admin", false);
      if (data && data.ok === true && data.authenticated === true && data.user) {
        setAuthDebug({
          authenticated: true,
          role: normalizeAuthRole(data.user.role),
          user_id: data.user.id,
          mode: "auth",
          available: true,
          error: ""
        });

        if (AUTH_ALWAYS_SHOW_LOGIN_PICKER) {
          applyAuthUserToState(data.user, { loginUser: false });
          return requestAuthLogout()
            .catch(() => null)
            .finally(() => {
              setAuthDebug({ authenticated: false, role: "", user_id: null, mode: "auth", available: true, error: "session-cleared-on-load" });
              logoutLocal();
              const resolvedName = String((data.user && data.user.display_name) || (data.user && data.user.email) || "deze gebruiker");
              setAuthLoginFeedback("Actieve sessie van " + resolvedName + " gevonden en gesloten. Kies hieronder een account.", false);
            });
        }

        setAuthLoginFeedback("", false);
        const hashViewOnLoad = String(window.location.hash || "").replace(/^#/, "");
        applyAuthUserToState(data.user, { loginUser: true });
        // Must run after setAuthDebug() above so authRuntime.authenticated is
        // already true; triggerReadApiWarmup() no-ops otherwise (this was a
        // real bug: a freshly created admin/employee vanished after a real
        // page reload because the warmup silently skipped itself every time).
        triggerReadApiWarmup();
        // applyAuthUserToState() -> login() always lands on the role's home
        // view. A real page reload should stay where the operator was
        // instead of bouncing back to the dashboard every time; showView()
        // itself safely no-ops on an unknown/empty hash.
        if (hashViewOnLoad) showView(hashViewOnLoad);
      } else {
        setAuthDebug({ authenticated: false, role: "", user_id: null, mode: "auth", available: true, error: "not-authenticated" });
        logoutLocal();
      }
    })
    .catch(() => {
      authRuntime.checked = true;
      authRuntime.available = false;
      applyAuthUiMode("demo");
      setAuthDebug({ authenticated: false, role: "", user_id: null, mode: "demo", available: false, error: "auth-unavailable" });
      logoutLocal();
    });
}

function triggerReadApiWarmup() {
  if (!(API_ENABLED && authRuntime.mode === "auth" && authRuntime.authenticated)) return;
  if (isLocalResetAuthoritative()) return;
  refreshBootstrapReadApi(true).then(() => refreshAdminWorkflowReadApi(true));
  refreshDashboardReadApi(true);
  refreshInvoicesReadApi("", true);
  refreshInvoicesReadApi("2026-07", true);
  refreshNotificationsReadApi(true);
  refreshAnnouncementsReadApi(true);
}

function setReadApiSource(section, source) {
  readApiSource[section] = source;
  readApiSource.overall = (readApiSource.bootstrap === "api" || readApiSource.dashboard === "api" || readApiSource.invoices === "api" || readApiSource.emailQueue === "api" || readApiSource.notifications === "api" || readApiSource.announcements === "api" || readApiSource.customerTimesheets === "api") ? "api" : "fallback";
}

function notificationTypeToLegacy(type) {
  const raw = String(type || "").toLowerCase();
  if (raw === "timesheet_submitted") return "submitted";
  if (raw === "timesheet_reminder") return "reminder";
  if (raw === "correction_required") return "correction";
  if (raw === "timesheet_approved") return "approved";
  if (raw === "invoice_ready") return "invoice";
  if (raw === "customer_timesheet_received") return "customer-timesheet";
  if (raw === "customer_timesheet_reminder") return "customer-timesheet-reminder";
  if (raw === "customer_timesheet_approved") return "customer-timesheet";
  if (raw === "customer_timesheet_resubmit") return "customer-timesheet";
  if (raw === "announcement") return "announcement";
  return raw || "notification";
}

function notificationTargetView(route) {
  const normalized = String(route || "").toLowerCase();
  if (!normalized) return state.currentRole === "employee" ? "employee-dashboard" : "dashboard";
  if (normalized === "employee-announcements") return "employee-announcements";
  return normalized;
}

