function firstBootstrapCompany(data) {
  if (!data || !Array.isArray(data.companies) || data.companies.length === 0) return null;
  return data.companies[0] || null;
}

function mergeBootstrapIntoState(data) {
  if (!data || data.ok !== true) return false;

  const company = firstBootstrapCompany(data);
  if (!company) return false;

  authRuntime.passwordResetDeliveryAvailable = Boolean(data.capabilities && data.capabilities.password_reset_delivery);

  // Settings/company fields: only overwrite fields that map 1-op-1.
  state.settings.organizationName = String(company.trade_name || state.settings.organizationName || "");
  state.settings.appName = String(company.app_name || state.settings.appName || "");
  state.settings.supportName = String(company.support_name || state.settings.supportName || "");
  state.settings.supportEmail = String(company.support_email || state.settings.supportEmail || "");
  // Leeg betekent hier "nooit ingevuld": dan blijft de ingebouwde tekst staan.
  if (company.website) state.settings.website = String(company.website);
  if (company.tagline) state.settings.tagline = String(company.tagline);
  state.settings.companyName = String(company.legal_name || state.settings.companyName || "");
  state.settings.invoiceNameDisplay = ["trade_and_legal", "legal_only"].includes(String(company.invoice_name_display || ""))
    ? String(company.invoice_name_display)
    : state.settings.invoiceNameDisplay;
  if (company.payment_term_days !== undefined && company.payment_term_days !== null) {
    state.settings.paymentTerm = String(company.payment_term_days);
  }

  const users = Array.isArray(data.users) ? data.users : [];
  const employees = Array.isArray(data.employees) ? data.employees : [];
  const assignments = Array.isArray(data.assignments) ? data.assignments : [];
  const counterparties = Array.isArray(data.counterparties) ? data.counterparties : [];
  const assignmentMailRoutes = Array.isArray(data.assignment_mail_routes) ? data.assignment_mail_routes : [];
  const recipients = Array.isArray(data.mail_recipients || data.mailRecipients) ? (data.mail_recipients || data.mailRecipients) : [];
  if (data.mail_channel_defaults && typeof data.mail_channel_defaults === "object") {
    mailStandaardTeksten = data.mail_channel_defaults;
  }
  if (data.mail_channel_shipped && typeof data.mail_channel_shipped === "object") {
    mailMeegeleverdeTeksten = data.mail_channel_shipped;
  }
  if (Array.isArray(data.mail_channel_customised)) {
    mailEigenTeksten = data.mail_channel_customised;
  }
  readApiRuntime.adminWorkflowPeriodKeys = (Array.isArray(data.periods) ? data.periods : [])
    .map(period => String(period && period.period_key || ""))
    .filter(periodKey => parsePeriodKey(periodKey))
    .filter((periodKey, index, all) => all.indexOf(periodKey) === index)
    .sort((left, right) => left.localeCompare(right));
  // Production is server-authoritative. The dedicated TEST host deliberately keeps
  // the complete demo catalogue, so switching roles never requires an F5 after a
  // role-scoped employee bootstrap response.
  const serverAccountsAreAuthoritative = authRuntime.mode === "auth" && !testAccountToolsAllowed();

  if (serverAccountsAreAuthoritative) {
    // Production must never mix browser demo identities with authenticated server data.
    state.admins = [];
    state.employees = [];
    state.settings.mailRecipients = [];
    if (!authRuntime.serverStateInitialized) {
      state.records = {};
      state.notifications = [];
      state.announcements = [];
      state.adminTaskMonthState = {};
      authRuntime.serverStateInitialized = true;
    }
  }

  state.settings.brandPrimary = normalizedBrandColor(String(company.brand_primary || state.settings.brandPrimary || "#0d1b38"), "#0d1b38");
  state.settings.brandAccent = normalizedBrandColor(String(company.brand_accent || state.settings.brandAccent || "#3abd9d"), "#3abd9d");
  state.settings.kvk = String(company.chamber_of_commerce_number || state.settings.kvk || "");
  state.settings.vat = String(company.vat_number || state.settings.vat || "");
  state.settings.iban = String(company.iban || state.settings.iban || "");
  state.settings.address = String(company.address_line || state.settings.address || "");
  state.settings.postalCity = [company.postal_code, company.city].filter(Boolean).join(" ").trim() || state.settings.postalCity;
  state.settings.phone = String(company.invoice_phone || state.settings.phone || "");
  state.settings.invoiceEmail = String(company.invoice_email || state.settings.invoiceEmail || "");
  if (company.customer_timesheet_reminder_enabled !== undefined && company.customer_timesheet_reminder_enabled !== null) {
    state.settings.customerTimesheetReminderEnabled = Number(company.customer_timesheet_reminder_enabled) === 1;
  }
  if (company.customer_timesheet_reminder_time) {
    state.settings.customerTimesheetReminderTime = String(company.customer_timesheet_reminder_time).slice(0, 5);
  }
  if (company.customer_timesheet_overdue_workdays !== undefined && company.customer_timesheet_overdue_workdays !== null) {
    state.settings.customerTimesheetOverdueWorkdays = Number(company.customer_timesheet_overdue_workdays) || state.settings.customerTimesheetOverdueWorkdays;
  }
  // The four klanturenstaat mail texts are server-side now. Empty means "never
  // changed": keep the built-in default rather than blanking the field.
  if (company.customer_timesheet_submission_subject) state.settings.customerTimesheetSubmissionSubject = String(company.customer_timesheet_submission_subject);
  if (company.customer_timesheet_submission_body) state.settings.customerTimesheetSubmissionBody = String(company.customer_timesheet_submission_body);
  if (company.customer_timesheet_broker_subject) state.settings.customerTimesheetBrokerSubject = String(company.customer_timesheet_broker_subject);
  if (company.customer_timesheet_broker_body) state.settings.customerTimesheetBrokerBody = String(company.customer_timesheet_broker_body);

  const companyUsers = users.filter(user => Number(user.company_id) === Number(company.id));
  const adminUsers = companyUsers.filter(user => String(user.role || "") === "administrator");
  const usersById = new Map(companyUsers.map(user => [Number(user.id), user]));
  const employeesByDbId = new Map(employees.map(employee => [Number(employee.id), employee]));
  const counterpartiesById = new Map(counterparties.map(counterparty => [Number(counterparty.id), counterparty]));
  const routesByAssignment = new Map();
  assignmentMailRoutes.forEach(route => {
    const assignmentId = Number(route.assignment_id || 0);
    if (!assignmentId) return;
    if (!routesByAssignment.has(assignmentId)) routesByAssignment.set(assignmentId, []);
    routesByAssignment.get(assignmentId).push(route);
  });

  // Admin/users: merge by email; keep local role-specific fields intact.
  adminUsers.forEach(user => {
    const email = String(user.email || "").trim().toLowerCase();
    const existing = state.admins.find(admin => String(admin.email || "").trim().toLowerCase() === email);
    if (existing) {
      existing.name = String(user.display_name || existing.name || "");
      existing.email = String(user.email || existing.email || "");
      existing.active = Number(user.active || 0) === 1;
      existing.dbUserId = Number(user.id);
    } else {
      state.admins.push({
        id: "db-" + String(user.id),
        dbUserId: Number(user.id),
        name: String(user.display_name || user.email || "Beheerder"),
        email: String(user.email || ""),
        active: Number(user.active || 0) === 1,
        emailNotificationsEnabled: true,
        photo: "",
        invitationPending: Number(user.password_ready || 0) !== 1
      });
    }
  });

  // Employees: merge onto existing local model by full name or email to avoid breaking rich demo fields.
  const employeeByDbId = new Map();
  const matchedDbEmployeeIds = new Set();
  state.employees.forEach(localEmployee => {
    const localName = String(localEmployee.name || "").trim().toLowerCase();
    const localEmail = String(localEmployee.email || "").trim().toLowerCase();
    const match = employees.find(dbEmployee => {
      const dbName = String(dbEmployee.full_name || "").trim().toLowerCase();
      const dbUser = usersById.get(Number(dbEmployee.user_id));
      const dbEmail = String(dbUser && dbUser.email || "").trim().toLowerCase();
      return (dbName && dbName === localName) || (dbEmail && dbEmail === localEmail);
    });
    if (!match) return;

    employeeByDbId.set(Number(match.id), localEmployee);
    matchedDbEmployeeIds.add(Number(match.id));
    const linkedUser = usersById.get(Number(match.user_id));
    localEmployee.name = String(match.full_name || localEmployee.name || "");
    localEmployee.role = String(match.job_title || localEmployee.role || "");
    // Account access is authoritative for the Teambeheer active/inactive filter. The
    // employee profile can still be active administratively after login access was
    // revoked, so showing only employees.active would leave a deactivated account
    // incorrectly visible under "Actief".
    localEmployee.active = linkedUser
      ? Number(linkedUser.active || 0) === 1
      : Number(match.active || 0) === 1;
    localEmployee.dbEmployeeId = Number(match.id);
    localEmployee.dbUserId = match.user_id ? Number(match.user_id) : null;
    if (match.employment_start_date) localEmployee.startDate = String(match.employment_start_date);
    if (match.weekly_contract_hours !== undefined && match.weekly_contract_hours !== null) {
      localEmployee.weeklyHours = Number(match.weekly_contract_hours);
    }
    if (linkedUser && linkedUser.email) localEmployee.email = String(linkedUser.email);
    if (linkedUser) localEmployee.invitationPending = Number(linkedUser.password_ready || 0) !== 1;
  });

  employees.forEach(dbEmployee => {
    const dbId = Number(dbEmployee.id || 0);
    if (!dbId || matchedDbEmployeeIds.has(dbId)) return;

    const linkedUser = usersById.get(Number(dbEmployee.user_id));
    const newEmployee = {
      id: dbId,
      dbEmployeeId: dbId,
      dbUserId: dbEmployee.user_id ? Number(dbEmployee.user_id) : null,
      name: String(dbEmployee.full_name || linkedUser && linkedUser.display_name || "Nieuwe medewerker"),
      email: String(linkedUser && linkedUser.email || "nieuwe-medewerker@example.invalid"),
      active: linkedUser
        ? Number(linkedUser.active || 0) === 1
        : Number(dbEmployee.active || 0) === 1,
      startDate: String(dbEmployee.employment_start_date || ""),
      notificationsEnabled: true,
      emailNotificationsEnabled: true,
      invitationPending: linkedUser ? Number(linkedUser.password_ready || 0) !== 1 : true,
      photo: "",
      role: String(dbEmployee.job_title || ""),
      client: "",
      broker: "",
      brokerEmail: "",
      invoiceRecipientName: "",
      brokerInvoiceAddress: "",
      invoiceProject: "",
      brokerMailEnabled: true,
      rate: 0,
      contract: "",
      weeklyHours: Number(dbEmployee.weekly_contract_hours || 0),
      projectCode: "",
      // Gelijk aan de serverstandaard (invoices.php). Een {klant}-token wordt
      // in formatInvoiceNumber niet ingevuld en belandde zo letterlijk op de PDF.
      invoiceTemplate: "INV-{jaar}-{maand}",
      // Leeg: dan geldt de standaardtekst van de server. Zie server/mail/templates.php.
      mailSubject: "",
      mailBody: "",
      brokerInvoiceAttachment: true,
      bookkeeperInvoiceAttachment: true,
      payrollInvoiceAttachment: false,
      mailRecipientRoutes: defaultMailRecipientRoutes(),
      customerTimesheetExpected: true,
      customerTimesheetDueWorkday: 5,
      customerTimesheetBrokerEnabled: false,
      customerTimesheetUseBrokerEmail: true,
      customerTimesheetBrokerEmail: "",
      invoiceWithoutCustomerTimesheetAllowed: true
    };

    state.employees.push(newEmployee);
    employeeByDbId.set(dbId, newEmployee);
    matchedDbEmployeeIds.add(dbId);
  });

  // Bind the shown profile to whoever is actually logged in. This used to run
  // only when the server catalogue was authoritative, so on the demo hosts
  // (localhost and uren-test) the selection kept pointing at the demo account
  // that happened to be picked -- logging in as Marc greeted you as Stasjo.
  // Re-bind only when the authenticated user changes, so a deliberate role
  // switch on TEST is not undone by the next background refresh.
  const boundUserId = Number(authDebug.user_id || authRuntime.identityUserId || 0);
  if (authRuntime.mode === "auth" && boundUserId > 0 && authRuntime.identityBoundUserId !== boundUserId) {
    const sessionEmail = String(authRuntime.identityEmail || "").toLowerCase();
    const boundAdmin = state.admins.find(admin => Number(admin.dbUserId || 0) === boundUserId)
      || state.admins.find(admin => String(admin.email || "").toLowerCase() === sessionEmail);
    const boundEmployee = state.employees.find(employee => Number(employee.dbUserId || 0) === boundUserId)
      || state.employees.find(employee => String(employee.email || "").toLowerCase() === sessionEmail);
    if (boundAdmin) state.currentAdminId = String(boundAdmin.id);
    if (boundEmployee) state.currentEmployeeId = Number(boundEmployee.id);
    if (boundAdmin || boundEmployee) authRuntime.identityBoundUserId = boundUserId;
  }

  if (serverAccountsAreAuthoritative) {
    const authenticatedUserId = Number(authDebug.user_id || 0);
    const authenticatedAdmin = state.admins.find(admin => Number(admin.dbUserId || 0) === authenticatedUserId);
    const authenticatedEmployee = state.employees.find(employee => Number(employee.dbUserId || 0) === authenticatedUserId);
    const selectedAdmin = authenticatedAdmin || state.admins.find(admin => admin.active !== false) || state.admins[0];
    const selectedEmployee = authenticatedEmployee || state.employees.find(employee => employee.active !== false) || state.employees[0];
    state.currentAdminId = selectedAdmin ? String(selectedAdmin.id) : "";
    state.currentEmployeeId = selectedEmployee ? Number(selectedEmployee.id) : 0;
  }

  // Assignments: merge selected mapping-friendly fields onto existing employee profiles.
  assignments.forEach(assignment => {
    const localEmployee = employeeByDbId.get(Number(assignment.employee_id));
    if (!localEmployee) return;
    localEmployee.dbAssignmentId = Number(assignment.id || 0);
    if (assignment.hourly_rate !== undefined && assignment.hourly_rate !== null) localEmployee.rate = Number(assignment.hourly_rate);
    if (assignment.invoice_project_name) localEmployee.invoiceProject = String(assignment.invoice_project_name);
    if (assignment.project_code) localEmployee.projectCode = String(assignment.project_code);
    if (assignment.invoice_number_template) localEmployee.invoiceTemplate = String(assignment.invoice_number_template);
    if (assignment.invoice_subject_template) localEmployee.mailSubject = String(assignment.invoice_subject_template);
    if (assignment.invoice_body_template) localEmployee.mailBody = String(assignment.invoice_body_template);
    if (assignment.agreement_number) localEmployee.agreementNumber = String(assignment.agreement_number);
    if (assignment.creditor_number) localEmployee.creditorNumber = String(assignment.creditor_number);
    if (assignment.contractor_number) localEmployee.contractorNumber = String(assignment.contractor_number);
    // Het contractlabel ("Vast · 36 uur") had geen kolom en ging bij elke herlaad
    // verloren. De app leidt er ook het aantal contracturen uit af, dus het is niet
    // alleen een opschrift.
    if (assignment.contract_label) localEmployee.contract = String(assignment.contract_label);
    if (assignment.customer_timesheet_due_workday !== undefined && assignment.customer_timesheet_due_workday !== null) {
      localEmployee.customerTimesheetDueWorkday = Number(assignment.customer_timesheet_due_workday);
    }
    if (assignment.customer_timesheet_broker_email) localEmployee.customerTimesheetBrokerEmail = String(assignment.customer_timesheet_broker_email);
    // Deze schakelaars werden wel opgeslagen en teruggegeven, maar nooit
    // teruggelezen: het profiel zette ze telkens hard op de standaardwaarde.
    // Wie het brokervinkje uitzette, zag het na een herlaad weer aanstaan.
    // Let op de expliciete null-controle: 0 is hier een geldige waarde.
    const vlag = (waarde, huidig) => (waarde === undefined || waarde === null ? huidig : Number(waarde) === 1);
    localEmployee.brokerMailEnabled = vlag(assignment.broker_mail_enabled, localEmployee.brokerMailEnabled);
    localEmployee.brokerInvoiceAttachment = vlag(assignment.broker_invoice_attachment, localEmployee.brokerInvoiceAttachment);
    localEmployee.bookkeeperInvoiceAttachment = vlag(assignment.bookkeeper_invoice_attachment, localEmployee.bookkeeperInvoiceAttachment);
    localEmployee.payrollInvoiceAttachment = vlag(assignment.payroll_invoice_attachment, localEmployee.payrollInvoiceAttachment);
    localEmployee.customerTimesheetExpected = vlag(assignment.customer_timesheet_expected, localEmployee.customerTimesheetExpected);
    localEmployee.customerTimesheetBrokerEnabled = vlag(assignment.customer_timesheet_broker_enabled, localEmployee.customerTimesheetBrokerEnabled);
    localEmployee.customerTimesheetUseBrokerEmail = vlag(assignment.customer_timesheet_use_broker_email, localEmployee.customerTimesheetUseBrokerEmail);
    localEmployee.invoiceWithoutCustomerTimesheetAllowed = vlag(assignment.invoice_without_customer_timesheet_allowed, localEmployee.invoiceWithoutCustomerTimesheetAllowed);

    const client = counterpartiesById.get(Number(assignment.client_id || 0));
    const broker = counterpartiesById.get(Number(assignment.broker_id || 0));
    if (client) {
      localEmployee.client = String(client.trade_name || client.legal_name || localEmployee.client || "");
    }
    if (broker) {
      localEmployee.broker = String(broker.trade_name || broker.legal_name || localEmployee.broker || "");
      localEmployee.brokerEmail = String(broker.invoice_email || localEmployee.brokerEmail || "");
      const brokerAddress = [broker.invoice_address_line, [broker.invoice_postal_code, broker.invoice_city].filter(Boolean).join(" ").trim()]
        .filter(Boolean)
        .join("\n");
      if (brokerAddress) {
        localEmployee.brokerInvoiceAddress = brokerAddress;
      }
    }

    const routes = routesByAssignment.get(Number(assignment.id || 0)) || [];
    if (!localEmployee.mailRecipientRoutes || typeof localEmployee.mailRecipientRoutes !== "object") {
      localEmployee.mailRecipientRoutes = defaultMailRecipientRoutes();
    }
    routes.forEach(route => {
      const key = String(route.recipient_key || route.mail_recipient_id || "").trim();
      if (!key) return;
      localEmployee.mailRecipientRoutes[key] = {
        enabled: Number(route.enabled || 0) === 1,
        invoiceAttachment: Number(route.include_invoice_pdf || 0) === 1,
        // Empty stays empty: that is what keeps this recipient inheriting the
        // assignment template instead of freezing a copy of it.
        mailSubject: String(route.subject_template || ""),
        mailBody: String(route.body_template || "")
      };
    });
  });

  // Mail recipients: merge by key/id where possible, add only missing recipients with safe defaults.
  recipients.forEach(recipient => {
    const key = String(recipient.recipient_key || recipient.id || "").trim();
    if (!key) return;
    const existing = (state.settings.mailRecipients || []).find(item => String(item.id) === key);
    if (existing) {
      existing.name = String(recipient.display_name || existing.name || "");
      existing.email = String(recipient.email || existing.email || "");
      existing.category = String(recipient.recipient_category || existing.category || "other");
      existing.active = Number(recipient.active || 0) === 1;
    } else {
      state.settings.mailRecipients.push({
        id: key,
        category: String(recipient.recipient_category || "other"),
        name: String(recipient.display_name || key),
        email: String(recipient.email || ""),
        active: Number(recipient.active || 0) === 1
      });
    }
  });

  Object.keys(state.records).forEach(periodKey => {
    state.employees.forEach(employee => {
      if (!state.records[periodKey][String(employee.id)]) {
        state.records[periodKey][String(employee.id)] = makeRecord(
          0,
          defaultContractHours(employee, periodKey),
          "draft",
          "concept",
          invoiceNumberFor(employee.id, periodKey),
          periodKey
        );
      }
    });
  });

  return true;
}

function dashboardApiForPeriod(periodKey) {
  const dashboard = readApiDebug.dashboard;
  if (!dashboard || !Array.isArray(dashboard.per_maand)) return null;
  const month = dashboard.per_maand.find(item => item && item.period_key === periodKey) || null;
  if (!month) return null;
  return { month };
}

function normalizeApiInvoiceStatus(status) {
  const normalized = String(status || "").toLowerCase();
  if (normalized === "ready") return "ready";
  if (normalized === "concept") return "concept";
  return "simulated";
}

function invoiceApiRowsForPeriod(periodKey) {
  const dataset = readApiDebug.invoicesByPeriod[periodKey] || readApiDebug.invoices || null;
  if (!dataset || !Array.isArray(dataset.items)) return null;
  return dataset.items.map(item => ({
    id: Number(item && item.id || 0),
    timesheetId: Number(item && item.timesheet_id || 0),
    employeeId: Number(item && item.employee_id || 0),
    assignmentId: Number(item && item.assignment_id || 0),
    invoiceNumber: String(item && item.invoice_number || ""),
    employeeName: String(item && item.employee_name || "Onbekend"),
    periodKey: String(item && item.period_key || periodKey),
    status: normalizeApiInvoiceStatus(item && item.status),
    statusRaw: String(item && item.status || ""),
    subtotal: Number(item && item.subtotal || 0),
    vatAmount: Number(item && item.vat_amount || 0),
    total: Number(item && item.total || 0),
    billableHours: Number(item && item.billable_hours || 0),
    hourlyRate: Number(item && item.hourly_rate || 0),
    vatPercentage: Number(item && item.vat_percentage || 0),
    timesheetStatus: String(item && item.timesheet_status || "").toLowerCase(),
    locked: Boolean(item && item.locked),
    lockedAt: String(item && item.locked_at || ""),
    invoiceDownloadUrl: String(item && item.invoice_download_url || ""),
    invoiceSource: String(item && item.invoice_source || "generated"),
    invoiceUploadReason: String(item && item.invoice_upload_reason || ""),
    invoiceOriginalFileName: String(item && item.invoice_original_file_name || ""),
    customerTimesheetStatus: String(item && item.customer_timesheet_status || "missing"),
    customerTimesheetFileName: String(item && item.customer_timesheet_file_name || ""),
    customerTimesheetNote: String(item && item.customer_timesheet_note || ""),
    customerTimesheetDownloadUrl: String(item && item.customer_timesheet_download_url || "")
  })).filter(item => item.periodKey === periodKey);
}

function invoiceCustomerTimesheetExternallyConfirmed(item) {
  return Boolean(
    item &&
    item.customerTimesheetStatus === "skipped" &&
    String(item.customerTimesheetNote || "").startsWith("Extern bevestigd:")
  );
}

function invoiceExternalConfirmationReason(item) {
  return String(item && item.customerTimesheetNote || "").replace(/^Extern bevestigd:\s*/, "");
}

function invoiceDocumentsComplete(item) {
  return Boolean(item && item.invoiceDownloadUrl && (item.customerTimesheetDownloadUrl || invoiceCustomerTimesheetExternallyConfirmed(item)));
}

function invoiceDocumentBadgesHtml(item) {
  const invoicePresent = Boolean(item.invoiceDownloadUrl);
  const timesheetPresent = Boolean(item.customerTimesheetDownloadUrl || invoiceCustomerTimesheetExternallyConfirmed(item));
  const badge = (kind, label, present) => {
    const stateLabel = present ? "aanwezig" : "ontbreekt";
    return '<button type="button" class="document-availability-badge ' + (present ? "is-present" : "is-missing") + '" data-invoice-documents="' + item.id + '" data-document-focus="' + kind + '" aria-label="' + escapeHtml(label + " " + stateLabel + " voor " + item.employeeName + "; documenten bekijken") + '">' + escapeHtml(label + (present ? " ✓" : " ontbreekt")) + '</button>';
  };
  return '<div class="invoice-document-badges">' +
    badge("invoice", "Factuur", invoicePresent) +
    badge("customer-timesheet", "Urenstaat", timesheetPresent) +
    '</div>';
}

function persistExternalCustomerTimesheetConfirmation(item, reviewNote) {
  const button = document.querySelector("#modal-confirm");
  button.disabled = true;
  writeCustomerTimesheetToApi("confirm_external", {
    employeeId: item.employeeId,
    assignmentId: item.assignmentId,
    periodKey: item.periodKey,
    reviewNote
  }).then(() => refreshInvoicesReadApi(item.periodKey, true))
    .then(() => {
      closeModal();
      renderInvoices();
      toast("De urenstaat staat groen als extern bevestigd.");
    })
    .catch(error => {
      button.disabled = false;
      toast(String(error && error.message || "Extern bevestigen is mislukt."));
    });
}

function showExternalCustomerTimesheetFinalWarning(item, reviewNote) {
  showModal({
    label: "Laatste controle",
    title: "Weet je het zeker?",
    message: item.employeeName + " · " + periodFromKey(item.periodKey).label,
    summary: '<div class="external-timesheet-warning" role="alert"><strong>Er wordt geen urenstaatbestand opgeslagen.</strong>' +
      '<p>Deze externe bevestiging telt wel als complete urenstaat en zet de maandcontrole op groen.</p></div>' +
      '<dl class="invoice-document-metadata"><div><dt>Reden</dt><dd>' + escapeHtml(reviewNote) + '</dd></div></dl>',
    confirm: "Ja, extern bevestigen",
    danger: true,
    action: () => persistExternalCustomerTimesheetConfirmation(item, reviewNote)
  });
}

function showExternalCustomerTimesheetConfirmation(item) {
  const reasons = [
    "Uren per e-mail goedgekeurd",
    "Uren in klantportaal goedgekeurd",
    "Klant gebruikt geen aparte urenstaat",
    "Bevestiging rechtstreeks door Backoffice ontvangen",
    "Anders, namelijk…"
  ];
  showModal({
    label: "Urenstaat afronden",
    title: "Extern bevestigd",
    message: item.employeeName + " · " + periodFromKey(item.periodKey).label,
    summary: '<div class="form-field"><label for="external-timesheet-reason">Reden</label><select id="external-timesheet-reason">' +
      reasons.map(reason => '<option value="' + escapeHtml(reason) + '">' + escapeHtml(reason) + '</option>').join("") +
      '</select></div><div class="form-field"><label for="external-timesheet-detail">Aanvulling (optioneel)</label><textarea id="external-timesheet-detail" maxlength="1000" placeholder="Bij Anders is een toelichting verplicht"></textarea></div>' +
      '<p class="modal-note">De app bewaart automatisch wie dit registreert en wanneer. Deze bevestiging telt als complete urenstaat voor de maandcontrole.</p>',
    confirm: "Reden controleren",
    action: () => {
      const reason = String(document.querySelector("#external-timesheet-reason")?.value || "").trim();
      const detail = String(document.querySelector("#external-timesheet-detail")?.value || "").trim();
      if (reason.startsWith("Anders") && detail.length < 5) {
        toast("Vul bij Anders een toelichting van minimaal 5 tekens in.");
        return;
      }
      const reviewNote = detail ? reason + " — " + detail : reason;
      showExternalCustomerTimesheetFinalWarning(item, reviewNote);
    },
    initialFocus: "#external-timesheet-reason-trigger"
  });
}

function restoreExternalCustomerTimesheet(item) {
  showModal({
    label: "Urenstaat herstellen",
    title: "Externe bevestiging intrekken?",
    message: item.employeeName + " · " + periodFromKey(item.periodKey).label,
    summary: "<p>De urenstaat wordt weer als ontbrekend getoond en blokkeert daarna opnieuw de maandcontrole.</p>",
    confirm: "Ja, bevestiging intrekken",
    danger: true,
    action: () => {
      const button = document.querySelector("#modal-confirm");
      button.disabled = true;
      writeCustomerTimesheetToApi("restore_missing", {
        employeeId: item.employeeId,
        assignmentId: item.assignmentId,
        periodKey: item.periodKey
      }).then(() => refreshInvoicesReadApi(item.periodKey, true))
        .then(() => {
          closeModal();
          renderInvoices();
          toast("De urenstaat staat weer als ontbrekend.");
        })
        .catch(error => {
          button.disabled = false;
          toast(String(error && error.message || "Terugdraaien is mislukt."));
        });
    }
  });
}

function showInvoiceDocuments(invoiceId, focusKind = "") {
  const item = (invoiceApiRowsForPeriod(currentPeriod().key) || []).find(row => Number(row.id) === Number(invoiceId));
  if (!item) {
    toast("De factuurdocumenten konden niet worden gevonden.");
    return;
  }
  const invoicePresent = Boolean(item.invoiceDownloadUrl);
  const customerExternallyConfirmed = invoiceCustomerTimesheetExternallyConfirmed(item);
  const customerPresent = Boolean(item.customerTimesheetDownloadUrl || customerExternallyConfirmed);
  const invoiceDocument = item.invoiceDownloadUrl
    ? '<div class="invoice-document-links"><button type="button" class="small-button" data-document-kind="invoice" data-doc-open="' + escapeHtml(item.invoiceDownloadUrl) + '">Openen</button><button type="button" class="text-button" data-doc-download="' + escapeHtml(item.invoiceDownloadUrl) + '" data-doc-name="Factuur-' + escapeHtml(safeFilename(String(item.invoiceNumber || item.periodKey || "document"))) + '.pdf">Downloaden</button></div>' +
      (item.invoiceSource === "external" ? '<dl class="invoice-document-metadata"><div><dt>Bron</dt><dd>Extern toegevoegd</dd></div>' +
        (item.invoiceOriginalFileName ? '<div><dt>Bestand</dt><dd>' + escapeHtml(item.invoiceOriginalFileName) + '</dd></div>' : '') +
        (item.invoiceUploadReason ? '<div><dt>Reden</dt><dd data-invoice-upload-reason>' + escapeHtml(item.invoiceUploadReason) + '</dd></div>' : '') + '</dl>' : '')
    : '<p class="invoice-document-missing-note">Factuur-PDF is nog niet beschikbaar.</p>';
  const customerDocument = item.customerTimesheetDownloadUrl
    ? '<div class="invoice-document-links"><button type="button" class="small-button" data-document-kind="customer-timesheet" data-doc-open="' + escapeHtml(item.customerTimesheetDownloadUrl) + '">Openen</button><button type="button" class="text-button" data-doc-download="' + escapeHtml(item.customerTimesheetDownloadUrl) + '" data-doc-name="Klanturenstaat-' + escapeHtml(safeFilename(String(item.periodKey || "document"))) + '.pdf">Downloaden</button></div>'
    : customerExternallyConfirmed
      ? '<p class="invoice-document-missing-note">Extern bevestigd' + (invoiceExternalConfirmationReason(item) ? ': ' + escapeHtml(invoiceExternalConfirmationReason(item)) : '') + '.</p>' +
        '<div class="invoice-document-restore"><button type="button" class="small-button document-restore-action" data-restore-external-timesheet>Externe bevestiging intrekken</button>' +
        '<small>De urenstaat wordt daarna weer als ontbrekend gemarkeerd.</small></div>'
      : '<p class="invoice-document-missing-note">Geen klanturenstaatbestand bewaard.</p>';
  const upload = !item.customerTimesheetDownloadUrl
    ? '<div class="form-field invoice-document-upload"><label for="invoice-customer-timesheet-file">Urenstaat toevoegen</label><input id="invoice-customer-timesheet-file" type="file" accept="application/pdf,image/jpeg,image/png"><small>PDF, JPG of PNG. Afbeeldingen worden veilig als PDF opgeslagen.</small>' +
      (!customerExternallyConfirmed ? '<button type="button" class="small-button" data-confirm-external-timesheet>Geen bestand? Extern bevestigen</button>' : '') + '</div>'
    : '';
  const invoiceUpload = !item.invoiceDownloadUrl
    ? '<div class="form-field invoice-document-upload"><label for="external-invoice-file">Factuur toevoegen</label><input id="external-invoice-file" type="file" accept="application/pdf,image/jpeg,image/png"><label for="external-invoice-reason">Reden</label><input id="external-invoice-reason" type="text" maxlength="250" placeholder="Bijvoorbeeld: ontvangen van broker"><small>Een bestaand factuurdocument wordt nooit stil overschreven.</small></div>'
    : '';
  const card = (kind, title, present, documentHtml, uploadHtml, presentLabel = "Aanwezig") => '<section class="invoice-document-card ' + (present ? "is-present" : "is-missing") + '" data-document-card="' + kind + '">' +
    '<header><strong>' + title + '</strong><span class="document-status-pill ' + (present ? "is-present" : "is-missing") + '">' + (present ? presentLabel : "Ontbreekt") + '</span></header>' +
    '<div class="invoice-document-card-body">' + documentHtml + uploadHtml + '</div></section>';
  const hasUpload = !invoicePresent || !customerPresent;
  const initialFocus = focusKind === "invoice"
    ? (invoicePresent ? '[data-document-kind="invoice"]' : "#external-invoice-file")
    : focusKind === "customer-timesheet"
      ? (customerPresent ? '[data-document-kind="customer-timesheet"]' : "#invoice-customer-timesheet-file")
      : "";
  const initialConfirm = focusKind === "invoice" && !invoicePresent
    ? "Factuur opslaan"
    : focusKind === "customer-timesheet" && !customerPresent
      ? "Urenstaat opslaan"
      : hasUpload ? "Bestand opslaan" : "Sluiten";
  showModal({
    label: "Documentarchief",
    title: item.invoiceNumber,
    message: item.employeeName + " · " + periodFromKey(item.periodKey).label,
    summary: '<div class="invoice-document-card-grid">' +
      card("invoice", "Factuur", invoicePresent, invoiceDocument, invoiceUpload) +
      card("customer-timesheet", "Urenstaat", customerPresent, customerDocument, upload, customerExternallyConfirmed ? "Extern bevestigd" : "Aanwezig") +
      '</div>',
    confirm: initialConfirm,
    action: hasUpload ? () => {
      const invoiceInput = document.querySelector("#external-invoice-file");
      const invoiceFile = invoiceInput && invoiceInput.files && invoiceInput.files[0];
      if (invoiceFile) {
        const reason = String(document.querySelector("#external-invoice-reason")?.value || "").trim();
        if (reason.length < 5) {
          toast("Vul een reden van minimaal 5 tekens in.");
          return;
        }
        const allowed = ["application/pdf", "image/jpeg", "image/png"];
        if (!allowed.includes(String(invoiceFile.type || "").toLowerCase())) {
          toast("Alleen PDF, JPG en PNG zijn toegestaan.");
          return;
        }
        const button = document.querySelector("#modal-confirm");
        button.disabled = true;
        requestAuthCsrf().then(token => {
          const data = new FormData();
          data.append("action", "upload_external");
          data.append("invoice_id", String(item.id));
          data.append("reason", reason);
          data.append("file", invoiceFile, invoiceFile.name || "factuur");
          return fetch(READ_API_INVOICES_PATH, { method: "POST", headers: { "Accept": "application/json", "X-CSRF-Token": token }, body: data });
        }).then(response => response.json().catch(() => ({})).then(data => ({ ok: response.ok, data })))
          .then(result => {
            if (!result.ok || result.data.ok !== true) throw new Error(String(result.data.message || "Uploaden is mislukt."));
            return refreshInvoicesReadApi(item.periodKey, true);
          }).then(() => { closeModal(); renderInvoices(); toast("Externe factuur is als PDF opgeslagen."); })
          .catch(error => { button.disabled = false; toast(String(error && error.message || "Uploaden is mislukt.")); });
        return;
      }
      const input = document.querySelector("#invoice-customer-timesheet-file");
      const file = input && input.files && input.files[0];
      if (!file) {
        toast(input ? "Kies eerst een PDF-, JPG- of PNG-bestand." : "Kies eerst een externe factuur.");
        return;
      }
      const allowed = ["application/pdf", "image/jpeg", "image/png"];
      if (!allowed.includes(String(file.type || "").toLowerCase())) {
        toast("Alleen PDF, JPG en PNG zijn toegestaan.");
        return;
      }
      const button = document.querySelector("#modal-confirm");
      button.disabled = true;
      writeCustomerTimesheetToApi("save_draft", {
        employeeId: item.employeeId,
        assignmentId: item.assignmentId,
        periodKey: item.periodKey,
        file
      }).then(() => refreshInvoicesReadApi(item.periodKey, true))
        .then(() => {
          closeModal();
          renderInvoices();
          toast("Klanturenstaat is veilig als document opgeslagen.");
        })
        .catch(error => {
          button.disabled = false;
          toast(String(error && error.message || "Uploaden is mislukt."));
        });
    } : closeModal,
    wide: true,
    initialFocus
  });
  if (hasUpload) {
    const invoiceInput = document.querySelector("#external-invoice-file");
    const timesheetInput = document.querySelector("#invoice-customer-timesheet-file");
    const confirmButton = document.querySelector("#modal-confirm");
    if (invoiceInput) invoiceInput.addEventListener("change", () => {
      if (timesheetInput) timesheetInput.value = "";
      confirmButton.textContent = "Factuur opslaan";
    });
    if (timesheetInput) timesheetInput.addEventListener("change", () => {
      if (invoiceInput) invoiceInput.value = "";
      confirmButton.textContent = "Urenstaat opslaan";
    });
  }
  const confirmExternalButton = document.querySelector("[data-confirm-external-timesheet]");
  if (confirmExternalButton) confirmExternalButton.addEventListener("click", () => showExternalCustomerTimesheetConfirmation(item));
  const restoreExternalButton = document.querySelector("[data-restore-external-timesheet]");
  if (restoreExternalButton) restoreExternalButton.addEventListener("click", () => restoreExternalCustomerTimesheet(item));
}

function emailQueueItemsByInvoiceId(periodKey) {
  const rows = invoiceApiRowsForPeriod(periodKey) || [];
  const invoiceIds = new Set(rows.map(row => Number(row.id || 0)).filter(id => id > 0));
  const queueItems = Array.isArray(readApiDebug.emailQueue && readApiDebug.emailQueue.items)
    ? readApiDebug.emailQueue.items
    : [];
  const byInvoice = new Map();
  queueItems.forEach(item => {
    const invoiceId = Number(item && item.invoice_id || 0);
    if (invoiceId <= 0 || !invoiceIds.has(invoiceId)) return;
    const status = String(item && item.status || "").toLowerCase();
    if (!status) return;
    if (!byInvoice.has(invoiceId)) byInvoice.set(invoiceId, []);
    byInvoice.get(invoiceId).push({
      status,
      channel: String(item && item.channel || ""),
      dryRun: Boolean(item && item.dry_run)
    });
  });
  return byInvoice;
}

function syncInvoiceStatusesFromApi(periodKey) {
  if (!(API_ENABLED && authRuntime.mode === "auth" && state.currentRole === "admin")) return false;
  // A local reset must stay authoritative: cached read-API rows from before the reset must never
  // overwrite the freshly-reset local invoice/payroll status.
  if (isLocalResetAuthoritative()) return false;
  const key = parsePeriodKey(periodKey) ? periodKey : "";
  if (!key) return false;

  const rows = invoiceApiRowsForPeriod(key);
  if (!rows || !rows.length) return false;

  const deliveriesByInvoice = emailQueueItemsByInvoiceId(key);
  let changed = false;

  state.employees
    .filter(employee => employeeStartedByPeriodEnd(employee, key))
    .forEach(employee => {
      const record = recordFor(employee.id, key);
      const row = rows.find(item => item.invoiceNumber === record.invoiceNumber)
        || rows.find(item => item.employeeName === employee.name);
      if (!row) return;

      const deliveries = deliveriesByInvoice.get(Number(row.id)) || [];
      // Dry-run items (LOCAL) always stay queued and count as implicit proof.
      // Real deliveries (TEST/PROD) must all be sent before the task closes.
      const realDeliveries = deliveries.filter(item => !item.dryRun);
      const hasDeliveryProof = deliveries.length > 0 && (
        realDeliveries.length === 0
          ? deliveries.every(item => item.dryRun)
          : realDeliveries.every(item => item.status === "sent")
      );
      const serverTimesheetStatus = ["draft", "submitted", "correction", "approved", "invoiced"].includes(row.timesheetStatus)
        ? row.timesheetStatus
        : "";
      const serverTimesheetApproved = ["approved", "invoiced"].includes(serverTimesheetStatus);
      const localTimesheetApproved = ["approved", "invoiced"].includes(record.timesheetStatus);
      // A direct timesheet read/write carries its own optimistic-lock version and is newer and
      // more authoritative than the denormalized status embedded in the invoice projection.
      // Without this precedence, a briefly lagging invoice row can hide the invoice task that
      // was created by the approval response we just received.
      const hasVersionedTimesheetState = Number(record.serverVersion || 0) > 0;
      const effectiveTimesheetApproved = hasVersionedTimesheetState
        ? localTimesheetApproved
        : (serverTimesheetStatus ? serverTimesheetApproved : localTimesheetApproved);
      // Timesheet approval is the business transition that opens the invoice task. The invoice
      // read model can briefly remain `concept` after that write; it must not hide the newly
      // created Backoffice action. Delivery proof (or an already locked invoice row) remains
      // authoritative and closes the task.
      const nextInvoiceStatus = hasDeliveryProof || row.status === "simulated"
        ? "simulated"
        : !hasVersionedTimesheetState && serverTimesheetStatus && !serverTimesheetApproved
          ? "concept"
          : effectiveTimesheetApproved
            ? "ready"
            : row.status;
      const nextPayrollStatus = hasDeliveryProof
        ? "simulated"
        : (nextInvoiceStatus === "ready" ? "ready" : "concept");

      if (record.invoiceNumber !== row.invoiceNumber && row.invoiceNumber) {
        record.invoiceNumber = row.invoiceNumber;
        changed = true;
      }
      const invoiceReadMayAdvanceTimesheet = serverTimesheetApproved || !localTimesheetApproved;
      if (serverTimesheetStatus && invoiceReadMayAdvanceTimesheet && record.timesheetStatus !== serverTimesheetStatus) {
        record.timesheetStatus = serverTimesheetStatus;
        changed = true;
      }
      if (record.invoiceStatus !== nextInvoiceStatus) {
        record.invoiceStatus = nextInvoiceStatus;
        changed = true;
      }
      if (record.payrollStatus !== nextPayrollStatus) {
        record.payrollStatus = nextPayrollStatus;
        changed = true;
      }
      normalizeRecord(record, employee, key);
    });

  return changed;
}

function fetchReadApi(path) {
  if (!API_ENABLED || isLocalResetAuthoritative()) return Promise.resolve(null);
  if (authRuntime.mode === "auth" && !authRuntime.authenticated) return Promise.resolve(null);
  try {
    return fetch(path, { method: "GET", headers: { "Accept": "application/json" } })
      .then(resp => {
        if (!resp.ok) throw new Error("HTTP " + resp.status);
        return resp.json();
      })
      .then(data => {
        if (!data || data.ok !== true) return null;
        return data;
      })
      .catch(error => {
        console.warn("Read-only API request failed", path, error);
        return null;
      });
  } catch (error) {
    console.warn("Read-only API init failed", path, error);
    return Promise.resolve(null);
  }
}

function refreshDashboardReadApi(force) {
  if (!(API_ENABLED && authRuntime.mode === "auth")) return;
  const now = Date.now();
  if (!force && (readApiRuntime.dashboardInFlight || (now - readApiRuntime.lastDashboardAt) < 15000)) return;
  readApiRuntime.dashboardInFlight = true;
  fetchReadApi(READ_API_DASHBOARD_PATH)
    .then(data => {
      readApiRuntime.lastDashboardAt = Date.now();
      if (!data) return;
      readApiDebug.dashboard = data;
      const dashboardViewActive = document.querySelector("#view-dashboard")?.classList.contains("is-active");
      if (dashboardViewActive) renderDashboard();
    })
    .finally(() => {
      readApiRuntime.dashboardInFlight = false;
    });
}

function refreshBootstrapReadApi(force) {
  if (!(API_ENABLED && authRuntime.mode === "auth")) return Promise.resolve(null);
  // A local reset must stay authoritative: never let a (possibly in-flight/delayed) bootstrap merge
  // re-inject server employees/records once the operator has reset to the local demo baseline.
  if (isLocalResetAuthoritative()) return Promise.resolve(null);
  const now = Date.now();
  if (!force && (readApiRuntime.bootstrapInFlight || (now - readApiRuntime.lastBootstrapAt) < 30000)) return Promise.resolve(null);
  readApiRuntime.bootstrapInFlight = true;
  return fetchReadApi("/server/api/bootstrap.php")
    .then(data => {
      readApiRuntime.lastBootstrapAt = Date.now();
      if (!data || isLocalResetAuthoritative()) {
        setReadApiSource("bootstrap", "fallback");
        return;
      }
      readApiDebug.bootstrap = data;
      const merged = mergeBootstrapIntoState(data);
      setReadApiSource("bootstrap", merged ? "api" : "fallback");
      if (merged) {
        renderAll();
      }
    })
    .catch(() => {
      setReadApiSource("bootstrap", "fallback");
    })
    .finally(() => {
      readApiRuntime.bootstrapInFlight = false;
    });
}

// Backoffice totals cover every relevant month, not only the month currently
// visible in the UI. Hydrate the full server workflow after bootstrap so a
// month switch can never create or remove unrelated work from the counters.
function settlePromiseFactoriesWithConcurrency(factories, concurrency = 4) {
  const tasks = Array.isArray(factories) ? factories : [];
  if (!tasks.length) return Promise.resolve([]);
  const results = new Array(tasks.length);
  let nextIndex = 0;
  const worker = () => {
    const index = nextIndex++;
    if (index >= tasks.length) return Promise.resolve();
    return Promise.resolve()
      .then(() => tasks[index]())
      .then(
        value => { results[index] = { status: "fulfilled", value }; },
        reason => { results[index] = { status: "rejected", reason }; }
      )
      .then(worker);
  };
  const workerCount = Math.max(1, Math.min(Number(concurrency) || 1, tasks.length));
  return Promise.all(Array.from({ length: workerCount }, worker)).then(() => results);
}

function refreshAdminWorkflowReadApi(force = false) {
  if (!(API_ENABLED && authRuntime.mode === "auth" && authRuntime.authenticated && state.currentRole === "admin")) {
    return Promise.resolve(false);
  }
  if (isLocalResetAuthoritative()) {
    readApiRuntime.adminWorkflowHydrated = true;
    return Promise.resolve(false);
  }

  const now = Date.now();
  if (!force && (readApiRuntime.adminWorkflowInFlight || (now - readApiRuntime.lastAdminWorkflowAt) < 15000)) {
    return Promise.resolve(false);
  }

  const currentMonthKey = currentCalendarPeriodKey();
  const periodKeys = readApiRuntime.adminWorkflowPeriodKeys
    .filter(periodKey => parsePeriodKey(periodKey) && periodKey <= currentMonthKey);
  const employees = activeEmployees();
  if (!periodKeys.length || !employees.length) {
    readApiRuntime.adminWorkflowHydrated = true;
    return Promise.resolve(false);
  }

  readApiRuntime.adminWorkflowInFlight = true;
  const reads = [];
  periodKeys.forEach(periodKey => {
    employees
      .filter(employee => !employee.startDate || employee.startDate.slice(0, 7) <= periodKey)
      .forEach(employee => {
        reads.push(() => refreshTimesheetReadApi(periodKey, employee.id, force));
        reads.push(() => refreshCustomerTimesheetReadApi(periodKey, employee.id, force));
      });
  });

  // A growing company and month history can otherwise create hundreds of
  // simultaneous PHP requests at login. A small queue keeps the UI responsive
  // and prevents one slow read from starving auth/navigation requests.
  return settlePromiseFactoriesWithConcurrency(reads, 4)
    .then(() => refreshInvoicesReadApi("", true))
    .then(() => {
      readApiRuntime.lastAdminWorkflowAt = Date.now();
      readApiRuntime.adminWorkflowHydrated = true;
      renderAll();
      return true;
    })
    .finally(() => {
      readApiRuntime.adminWorkflowInFlight = false;
    });
}

function refreshInvoicesReadApi(periodKey, force) {
  if (!(API_ENABLED && authRuntime.mode === "auth")) return Promise.resolve(null);
  const period = parsePeriodKey(periodKey) ? periodKey : "";
  const now = Date.now();
  const lastAt = period ? Number(readApiRuntime.lastInvoicesByPeriod[period] || 0) : readApiRuntime.lastInvoicesAt;
  if (!force && (readApiRuntime.invoicesInFlight || (now - lastAt) < 15000)) return Promise.resolve(null);
  readApiRuntime.invoicesInFlight = true;
  const endpoint = period
    ? READ_API_INVOICES_PATH + "?period=" + encodeURIComponent(period)
    : READ_API_INVOICES_PATH;
  return fetchReadApi(endpoint)
    .then(data => {
      const fetchedAt = Date.now();
      if (period) readApiRuntime.lastInvoicesByPeriod[period] = fetchedAt;
      else readApiRuntime.lastInvoicesAt = fetchedAt;
      if (!data) return;
      if (period) readApiDebug.invoicesByPeriod[period] = data;
      else readApiDebug.invoices = data;
      let invoiceStateChanged = false;
      if (period) {
        invoiceStateChanged = syncInvoiceStatusesFromApi(period);
      } else {
        const periodKeys = [...new Set((data.items || []).map(item => String(item && item.period_key || "")).filter(parsePeriodKey))];
        periodKeys.forEach(periodKey => {
          if (syncInvoiceStatusesFromApi(periodKey)) invoiceStateChanged = true;
        });
      }
      const invoicesViewActive = document.querySelector("#view-invoices")?.classList.contains("is-active");
      const dashboardViewActive = document.querySelector("#view-dashboard")?.classList.contains("is-active");
      if (invoiceStateChanged && dashboardViewActive) renderAll();
      else if (invoicesViewActive && (!period || period === currentPeriod().key)) renderInvoices();
    })
    .finally(() => {
      readApiRuntime.invoicesInFlight = false;
    });
}

function refreshEmailQueueReadApi(force = false) {
  if (!(API_ENABLED && authRuntime.mode === "auth" && state.currentRole === "admin")) return Promise.resolve(null);
  const now = Date.now();
  if (!force && (readApiRuntime.emailQueueInFlight || (now - readApiRuntime.lastEmailQueueAt) < 15000)) return Promise.resolve(null);
  readApiRuntime.emailQueueInFlight = true;

  const params = new URLSearchParams({
    limit: String(readApiRuntime.mailDeliveryLimit),
    offset: String(readApiRuntime.mailDeliveryOffset)
  });
  if (readApiRuntime.mailDeliveryStatus) params.set("status", readApiRuntime.mailDeliveryStatus);
  if (readApiRuntime.mailDeliveryQuery) params.set("q", readApiRuntime.mailDeliveryQuery);

  return fetchReadApi("/server/api/email-queue.php?" + params.toString())
    .then(data => {
      readApiRuntime.lastEmailQueueAt = Date.now();
      if (!data) {
        setReadApiSource("emailQueue", "fallback");
        return null;
      }
      readApiDebug.emailQueue = data;
      setReadApiSource("emailQueue", "api");
      renderMailDeliveryHistory();
      const cachedPeriodKeys = [...new Set([
        currentPeriod().key,
        ...Object.keys(readApiDebug.invoicesByPeriod || {}),
        ...((readApiDebug.invoices && readApiDebug.invoices.items) || []).map(item => String(item && item.period_key || ""))
      ].filter(parsePeriodKey))];
      const changed = cachedPeriodKeys.some(syncInvoiceStatusesFromApi);
      if (changed && (document.querySelector("#view-invoices")?.classList.contains("is-active") || document.querySelector("#view-dashboard")?.classList.contains("is-active"))) {
        renderAll();
      }
      return data;
    })
    .finally(() => {
      readApiRuntime.emailQueueInFlight = false;
    });
}

function refreshMailAcceptanceReadApi(force = false) {
  if (!(API_ENABLED && authRuntime.mode === "auth" && state.currentRole === "admin")) return Promise.resolve(null);
  const now = Date.now();
  if (!force && (readApiRuntime.mailAcceptanceInFlight || (now - readApiRuntime.lastMailAcceptanceAt) < 15000)) return Promise.resolve(null);
  readApiRuntime.mailAcceptanceInFlight = true;

  return fetchReadApi(MAIL_ACCEPTANCE_API_PATH)
    .then(data => {
      readApiRuntime.lastMailAcceptanceAt = Date.now();
      readApiDebug.mailAcceptance = data;
      setReadApiSource("mailAcceptance", data ? "api" : "fallback");
      renderMailAcceptanceConsole();
      return data;
    })
    .finally(() => {
      readApiRuntime.mailAcceptanceInFlight = false;
    });
}

function refreshCustomerTimesheetReadApi(periodKey, employeeId, force = false) {
  if (!isCustomerTimesheetApiMode() || !["admin", "employee"].includes(state.currentRole)) return Promise.resolve(null);
  const period = parsePeriodKey(periodKey) ? periodKey : "";
  const employee = Number(employeeId || 0);
  if (!period || !Number.isFinite(employee) || employee <= 0) return Promise.resolve(null);
  if (state.currentRole === "employee" && Number(currentEmployee()?.id || 0) !== employee) return Promise.resolve(null);

  const key = period + ":" + employee;
  const mutationEpoch = Number(readApiRuntime.customerTimesheetMutationEpochByKey[key] || 0);
  const now = Date.now();
  const lastAt = Number(readApiRuntime.lastCustomerTimesheetsByPeriod[key] || 0);
  // Zelfde reden als bij de urenstaat: wie op een al lopende lezing stuitte, kreeg
  // null en concludeerde dat er niets was veranderd. Bij de takentellers betekent
  // dat een openstaande taak die blijft staan nadat hij is afgehandeld.
  const lopend = readApiRuntime.customerTimesheetsInFlight[key];
  if (lopend) return lopend;
  if (!force && (now - lastAt) < 15000) return Promise.resolve(null);

  const endpoint = WRITE_CUSTOMER_TIMESHEET_PATH + "?period=" + encodeURIComponent(period) + "&employee_id=" + encodeURIComponent(String(employee));

  const inFlight = fetchReadApi(endpoint)
    .then(data => {
      readApiRuntime.lastCustomerTimesheetsByPeriod[key] = Date.now();
      if (isLocalResetAuthoritative()) return null;
      if (Number(readApiRuntime.customerTimesheetMutationEpochByKey[key] || 0) !== mutationEpoch) return null;
      if (!data || data.found !== true || !data.customer_timesheet) {
        if (!data || data.ok !== true || data.found !== false) {
          setReadApiSource("customerTimesheets", "fallback");
          return null;
        }
        if (!readApiDebug.customerTimesheetsByPeriod[period]) readApiDebug.customerTimesheetsByPeriod[period] = {};
        readApiDebug.customerTimesheetsByPeriod[period][String(employee)] = data;
        applyMissingCustomerTimesheetApiRecord(employee, period);
      } else {
        if (!readApiDebug.customerTimesheetsByPeriod[period]) readApiDebug.customerTimesheetsByPeriod[period] = {};
        readApiDebug.customerTimesheetsByPeriod[period][String(employee)] = data;
        applyCustomerTimesheetApiRecord(employee, period, data);
      }
      setReadApiSource("customerTimesheets", "api");

      const dashboardViewActive = document.querySelector("#view-dashboard")?.classList.contains("is-active");
      if (dashboardViewActive && period === currentPeriod().key) {
        renderCustomerTimesheetAdmin();
        // Customer-timesheet status feeds admin task totals (hero counter, task queue,
        // nav badges); without this they go stale until an unrelated full re-render happens.
        renderDashboardActions();
        renderAdminTaskQueue();
      }
      return data;
    })
    .finally(() => {
      readApiRuntime.customerTimesheetsInFlight[key] = null;
    });
  readApiRuntime.customerTimesheetsInFlight[key] = inFlight;
  return inFlight;
}

function currentPeriod() {
  if (!parsePeriodKey(state.selectedPeriodKey)) state.selectedPeriodKey = "2026-07";
  return periodFromKey(state.selectedPeriodKey);
}

function employeeById(id) {
  return state.employees.find(employee => employee.id === Number(id));
}

function adminById(id) {
  return state.admins.find(admin => admin.id === String(id));
}

function activeEmployees() {
  return state.employees.filter(employee => employee.active !== false);
}

function activeAdmins() {
  return state.admins.filter(admin => admin.active !== false);
}

function currentAdmin() {
  return adminById(state.currentAdminId) || activeAdmins()[0] || state.admins[0];
}

function currentEmployee() {
  const selected = employeeById(state.currentEmployeeId);
  if (selected && selected.active !== false) return selected;
  return activeEmployees()[0] || state.employees[0];
}

function mailRecipientById(id) {
  return (state.settings.mailRecipients || []).find(recipient => String(recipient.id) === String(id));
}

function activeMailRecipients() {
  return (state.settings.mailRecipients || []).filter(recipient => recipient.active !== false);
}

// De standaardteksten per soort ontvanger komen van de server, uit
// server/mail/templates.php. Ze staan hier niet nog een keer: één bron, anders
// laat dit scherm iets anders zien dan er verstuurd wordt.
let mailStandaardTeksten = {};

// Wat we meeleveren, los van wat dit bedrijf heeft ingesteld. Nodig om te kunnen
// laten zien waar "Terug naar de standaard" naartoe gaat.
let mailMeegeleverdeTeksten = {};

// Welke kanalen werkelijk een eigen tekst hebben staan. Afleiden uit een
// vergelijking met de meegeleverde tekst gaat mis: een opgeslagen tekst die
// toevallig gelijk is, is er nog steeds een en bevriest die tekst.
let mailEigenTeksten = [];

// Welke standaardtekst hoort bij welk soort ontvanger. Dit volgt de indeling in
// server/mail/queue.php: alleen boekhouding en salarisadministratie hebben een
// eigen kanaal, al het overige valt onder 'other'. De broker staat hier
// bewust niet tussen -- dat is geen vaste ontvanger maar een route op de opdracht.
function kanaalVoorSoort(category) {
  return ({ accounting: "accountant", payroll: "payroll" })[category] || "other";
}

function standaardTekstVoor(kanaal) {
  return mailStandaardTeksten[kanaal] || null;
}

// Wat er gebeurt als je dit veld leeg laat. Eén zin, voor elke ontvanger --
// er is geen uitzondering meer om uit te leggen. De tekst zelf staat bij
// Instellingen, zodat hij op één plek staat en niet in elk formulier.
const LEEG_IS_STANDAARD = "leeg = de standaardtekst";
const LEEG_IS_STANDAARD_UITLEG = "Laat leeg voor de standaardtekst. Die staat bij Instellingen, onder E-mail &amp; ontvangers.";

function recipientCategoryLabel(category) {
  return ({ accounting: "Boekhouding", payroll: "Salarisadministratie", other: "Overig" })[category] || "Overig";
}

function supportEmail() {
  return String(state.settings.supportEmail || SUPPORT_EMAIL).trim();
}

function supportName() {
  return String(state.settings.supportName || "Ondersteuning").trim();
}

// Een eigen logo van de organisatie gaat altijd voor: dat mogen we niet omkleuren,
// want dan is het hun logo niet meer.
function brandLogoUrl(ondergrond) {
  if (state.settings.brandLogo) return String(state.settings.brandLogo);
  return ondergrond === "donker" ? PATH_LOGO_OP_DONKER : PATH_LOGO_OP_LICHT;
}

function donkereModusActief() {
  return document.documentElement.dataset.theme === "dark";
}

function normalizedBrandColor(value, fallback) {
  const color = String(value || "").trim().toLowerCase();
  return /^#[0-9a-f]{6}$/.test(color) ? color : fallback;
}

function hexColorToRgb(value, fallback) {
  const color = normalizedBrandColor(value, fallback).slice(1);
  return [0, 2, 4].map(index => Number.parseInt(color.slice(index, index + 2), 16));
}

function applyOrganizationBranding() {
  const organizationName = String(state.settings.organizationName || "Organisatie").trim();
  const appName = String(state.settings.appName || "Uren & Facturatie").trim();
  document.title = organizationName + " · " + appName;
  document.querySelectorAll("[data-app-name]").forEach(element => { element.textContent = appName; });
  document.querySelectorAll("[data-brand-logo]").forEach(image => {
    // De desktopzijbalk heeft ook in de lichte modus een donkere ondergrond.
    // Kies daarom per logopositie het contrast, niet alleen op basis van het thema.
    const onDarkSurface = Boolean(image.closest("#sidebar-brand"));
    image.src = brandLogoUrl(onDarkSurface || donkereModusActief() ? "donker" : "licht");
    image.alt = organizationName + " logo";
  });
  const organizationLabel = document.querySelector("#organization-name");
  if (organizationLabel) organizationLabel.textContent = organizationName;
  const sidebarBrand = document.querySelector("#sidebar-brand");
  if (sidebarBrand) sidebarBrand.setAttribute("aria-label", organizationName + " " + appName);
  const helpSupportName = document.querySelector("#help-support-name");
  if (helpSupportName) helpSupportName.textContent = supportName();
  document.documentElement.style.setProperty("--navy", normalizedBrandColor(state.settings.brandPrimary, "#0d1b38"));
  document.documentElement.style.setProperty("--mint", normalizedBrandColor(state.settings.brandAccent, "#3abd9d"));
}

function mailRecipientRouteFor(employee, recipientId) {
  const routes = employee.mailRecipientRoutes || {};
  if (routes[recipientId]) return routes[recipientId];
  if (recipientId === "bookkeeper") return { enabled: true, invoiceAttachment: employee.bookkeeperInvoiceAttachment !== false };
  if (recipientId === "payroll") return { enabled: true, invoiceAttachment: employee.payrollInvoiceAttachment === true };
  return { enabled: false, invoiceAttachment: false };
}

function deliveryRoutesFor(employee) {
  const routes = [];
  if (employee.brokerMailEnabled !== false) routes.push({
    id: "broker",
    name: employee.broker || "Broker",
    email: employee.brokerEmail,
    invoiceAttachment: employee.brokerInvoiceAttachment !== false,
    kind: "broker"
  });
  activeMailRecipients().forEach(recipient => {
    const preference = mailRecipientRouteFor(employee, recipient.id);
    if (preference.enabled !== false) routes.push({
      id: recipient.id,
      name: recipient.name,
      email: recipient.email,
      invoiceAttachment: preference.invoiceAttachment === true,
      kind: recipient.id === "payroll" ? "payroll" : recipient.id === "bookkeeper" ? "bookkeeper" : "additional"
    });
  });
  return routes;
}

function syncLegacyRecipientSettings() {
  const bookkeeper = mailRecipientById("bookkeeper");
  const payroll = mailRecipientById("payroll");
  if (bookkeeper) {
    state.settings.bookkeeperName = bookkeeper.name;
    state.settings.bookkeeper = bookkeeper.email;
  }
  if (payroll) {
    state.settings.payrollName = payroll.name;
    state.settings.payroll = payroll.email;
  }
}

function weeklyHoursFor(employee) {
  const explicit = Number(employee.weeklyHours);
  if (Number.isFinite(explicit) && explicit >= 0) return explicit;
  const match = /(\d+(?:[.,]\d+)?)\s*uur/i.exec(employee.contract || "");
  return match ? Number(match[1].replace(",", ".")) : 40;
}

function defaultContractHours(employee, periodKey) {
  const period = periodFromKey(periodKey);
  return Math.round((period.businessDays * weeklyHoursFor(employee) / 5) * 10) / 10;
}

// Een {klant}-token in het nummer wordt de klantnaam, gestript tot letters en
// cijfers zodat het een bruikbaar factuurnummer blijft. Gelijk aan
// invoices_number_token() op de server.
function invoiceNumberToken(value) {
  const schoon = String(value || "").replace(/[^A-Za-z0-9]+/g, "");
  return schoon || "Klant";
}

function formatInvoiceNumber(template, periodKey, clientName) {
  const period = periodFromKey(periodKey);
  return String(template || "Factuur-{jaar}-{maand}")
    .replaceAll("{jaar}", String(period.year))
    .replaceAll("{maand}", period.month)
    .replaceAll("{klant}", invoiceNumberToken(clientName));
}

function invoiceNumberFor(employeeId, periodKey) {
  const employee = employeeById(employeeId);
  const clientName = (employee && employee.client) || "";
  const template = employee && employee.invoiceTemplate
    ? employee.invoiceTemplate
    : (invoiceNumberToken(clientName) || "Factuur") + "-{jaar}-{maand}";
  return formatInvoiceNumber(template, periodKey, clientName);
}

function normalizeRecord(record, employee, periodKey) {
  const period = periodFromKey(periodKey);
  const entries = emptyEntries(period.key);
  if (Array.isArray(record.entries)) {
    period.weekRows.forEach((week, weekIndex) => {
      week.days.forEach((day, dayIndex) => {
        if (!day) return;
        const value = Number(record.entries[weekIndex] && record.entries[weekIndex][dayIndex]);
        entries[weekIndex][dayIndex] = Number.isFinite(value) && value >= 0 ? value : 0;
      });
    });
  }
  record.entries = entries;
  if (!Number.isFinite(Number(record.contractHours))) record.contractHours = defaultContractHours(employee, period.key);
  record.contractHours = Number(record.contractHours) || 0;
  record.leave = Number(record.leave) || 0;
  record.sick = Number(record.sick) || 0;
  record.timesheetStatus = record.timesheetStatus || "draft";
  record.invoiceStatus = record.invoiceStatus || "concept";
  record.payrollStatus = record.payrollStatus || (record.timesheetStatus === "approved" ? "ready" : "concept");
  if (!Number.isFinite(Number(record.serverVersion)) || Number(record.serverVersion) <= 0) {
    record.serverVersion = null;
  } else {
    record.serverVersion = Number(record.serverVersion);
  }
  if (record.invoiceStatus === "simulated") record.payrollStatus = "simulated";
  record.invoiceNumber = record.invoiceNumber || invoiceNumberFor(employee.id, period.key);
  record.correctionHistory = Array.isArray(record.correctionHistory) ? record.correctionHistory : [];
  customerTimesheetFor(record);
  return record;
}

function customerTimesheetFor(record) {
  if (!record.customerTimesheet || typeof record.customerTimesheet !== "object") record.customerTimesheet = {};
  const defaults = blankCustomerTimesheet();
  Object.keys(defaults).forEach(key => {
    if (record.customerTimesheet[key] === undefined) record.customerTimesheet[key] = defaults[key];
  });
  return record.customerTimesheet;
}

function customerTimesheetStatusPill(documentRecord) {
  const status = customerTimesheetStatusLabels[customerTimesheetFor(documentRecord).status] || customerTimesheetStatusLabels.missing;
  return '<span class="status-pill ' + status[1] + '">' + status[0] + '</span>';
}

function safeFilePart(value) {
  return String(value || "bestand").trim().replace(/[^a-z0-9]+/gi, "_").replace(/^_+|_+$/g, "") || "bestand";
}

function customerTimesheetFileName(employee, periodKey) {
  return "Klanturenstaat_" + safeFilePart(employee.name) + "_" + periodKey + ".pdf";
}

function formatCustomerTimesheetTemplate(template, employee, periodKey) {
  const period = periodFromKey(periodKey);
  const monthLabel = String(period.month || "").toLowerCase();
  const values = {
    medewerker: employee.name,
    maand: monthLabel,
    jaar: period.year,
    backoffice: state.settings.supportName || "Path Backoffice",
    afzender: state.settings.supportName || "Path Backoffice",
    organisatie: state.settings.organizationName || "Path Consultancy"
  };
  return String(template || "").replace(/\{([a-z]+)\}/gi, (match, key) => values[key] === undefined ? match : values[key]);
}

function customerTimesheetSubmissionMail(employee, periodKey) {
  const record = customerTimesheetFor(recordFor(employee.id, periodKey));
  const defaultSubject = formatCustomerTimesheetTemplate(state.settings.customerTimesheetSubmissionSubject || DEFAULT_CUSTOMER_TIMESHEET_SUBMISSION_SUBJECT, employee, periodKey);
  const defaultBody = formatCustomerTimesheetTemplate(state.settings.customerTimesheetSubmissionBody || DEFAULT_CUSTOMER_TIMESHEET_SUBMISSION_BODY, employee, periodKey);
  return {
    subject: record.submissionSubject || defaultSubject,
    body: record.submissionBody || defaultBody
  };
}

function customerTimesheetBrokerMail(employee, periodKey) {
  return {
    subject: formatCustomerTimesheetTemplate(state.settings.customerTimesheetBrokerSubject || DEFAULT_CUSTOMER_TIMESHEET_BROKER_SUBJECT, employee, periodKey),
    body: formatCustomerTimesheetTemplate(state.settings.customerTimesheetBrokerBody || DEFAULT_CUSTOMER_TIMESHEET_BROKER_BODY, employee, periodKey)
  };
}

function customerTimesheetBrokerEmail(employee) {
  return employee.customerTimesheetUseBrokerEmail !== false
    ? employee.brokerEmail
    : employee.customerTimesheetBrokerEmail;
}

function ensurePeriodRecords(periodKey) {
  const period = periodFromKey(periodKey);
  if (!state.records || typeof state.records !== "object") state.records = {};
  if (!state.records[period.key]) state.records[period.key] = {};
  state.employees.forEach(employee => {
    const id = String(employee.id);
    if (!state.records[period.key][id]) {
      state.records[period.key][id] = makeRecord(
        0,
        defaultContractHours(employee, period.key),
        "draft",
        "concept",
        invoiceNumberFor(employee.id, period.key),
        period.key
      );
    } else {
      normalizeRecord(state.records[period.key][id], employee, period.key);
    }
  });
  return state.records[period.key];
}

function recordFor(employeeId, periodKey) {
  const key = periodKey || currentPeriod().key;
  return ensurePeriodRecords(key)[String(employeeId)];
}

function totalEntries(entries) {
  return entries.flat().reduce((sum, value) => sum + (Number(value) || 0), 0);
}

function correctionHistoryFor(record) {
  if (!Array.isArray(record.correctionHistory)) record.correctionHistory = [];
  return record.correctionHistory;
}

function latestCorrection(record) {
  const history = correctionHistoryFor(record);
  return history.length ? history[history.length - 1] : null;
}

function activeCorrection(record) {
  const history = correctionHistoryFor(record);
  return [...history].reverse().find(item => !item.resubmittedAt) || null;
}

function correctionTimestamp() {
  const now = new Date();
  let label;
  try {
    label = new Intl.DateTimeFormat("nl-NL", {
      day: "numeric",
      month: "long",
      year: "numeric",
      hour: "2-digit",
      minute: "2-digit",
      timeZone: "Europe/Amsterdam"
    }).format(now);
  } catch {
    label = now.toLocaleString("nl-NL");
  }
  return { iso: now.toISOString(), label };
}

function initials(name) {
  return String(name || "P").split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map(part => part[0])
    .join("")
    .toUpperCase();
}

function applyAvatar(element, name, photo) {
  if (!element) return;
  element.textContent = photo ? "" : initials(name);
  element.style.backgroundImage = photo ? 'url("' + String(photo).replaceAll('"', "%22") + '")' : "none";
}

function currentProfileData() {
  if (state.currentRole === "employee") {
    const employee = currentEmployee();
    return { source: employee, name: employee.name, email: employee.email, label: "Medewerker", photo: employee.photo || "" };
  }
  const admin = currentAdmin();
  return { source: admin, name: admin.name, email: admin.email, label: "Beheerder", photo: admin.photo || "" };
}

function updateLoginAdminPreview() {
  const picker = document.querySelector("#login-admin");
  if (!picker) return;
  const admin = adminById(picker.value) || currentAdmin();
  if (!admin) return;
  document.querySelector("#login-admin-trigger").textContent = admin.name + " · beheerder";
  document.querySelectorAll('[data-login-account-role="admin"]').forEach(button => button.classList.toggle("is-active", button.dataset.loginAccountId === String(admin.id)));
  applyAvatar(document.querySelector("#login-admin-avatar"), admin.name, admin.photo);
  document.querySelector("#login-admin-summary").textContent = admin.name + " · uren controleren, facturen en instellingen";
}

function renderLoginAdminPicker() {
  const picker = document.querySelector("#login-admin");
  const admins = activeAdmins();
  if (!picker || !admins.length) return;
  if (!adminById(state.currentAdminId) || adminById(state.currentAdminId).active === false) state.currentAdminId = admins[0].id;
  picker.innerHTML = admins.map(admin => '<option value="' + escapeHtml(admin.id) + '">' + escapeHtml(admin.name) + " · beheerder</option>").join("");
  picker.value = String(state.currentAdminId);
  document.querySelector("#login-admin-choices").innerHTML = admins.map(admin => '<button type="button" role="option" data-login-account-role="admin" data-login-account-id="' + escapeHtml(admin.id) + '"><strong>' + escapeHtml(admin.name) + '</strong><small>Beheerder · dashboard, controles en instellingen</small></button>').join("");
  updateLoginAdminPreview();
}

function updateLoginEmployeePreview() {
  const picker = document.querySelector("#login-employee");
  if (!picker) return;
  const employee = employeeById(picker.value) || currentEmployee();
  if (!employee) return;
  document.querySelector("#login-employee-trigger").textContent = employee.name + " · " + employee.client;
  document.querySelectorAll('[data-login-account-role="employee"]').forEach(button => button.classList.toggle("is-active", button.dataset.loginAccountId === String(employee.id)));
  document.querySelector("#login-employee-avatar").textContent = initials(employee.name);
  document.querySelector("#login-employee-summary").textContent = employee.name + " · eigen uren invullen en indienen";
}

function renderLoginEmployeePicker() {
  const picker = document.querySelector("#login-employee");
  const employees = activeEmployees();
  if (!picker) return;
  if (!employees.length) {
    picker.innerHTML = "";
    const choices = document.querySelector("#login-employee-choices");
    const trigger = document.querySelector("#login-employee-trigger");
    const summary = document.querySelector("#login-employee-summary");
    if (choices) choices.innerHTML = "";
    if (trigger) {
      trigger.textContent = "Nog geen medewerkers";
      trigger.disabled = true;
    }
    if (summary) summary.textContent = "Een beheerder maakt eerst je persoonlijke account aan.";
    return;
  }
  const trigger = document.querySelector("#login-employee-trigger");
  if (trigger) trigger.disabled = false;
  if (!employeeById(state.currentEmployeeId) || employeeById(state.currentEmployeeId).active === false) state.currentEmployeeId = employees[0].id;
  picker.innerHTML = employees
    .map(employee => '<option value="' + employee.id + '">' + escapeHtml(employee.name) + " · " + escapeHtml(employee.client) + "</option>")
    .join("");
  picker.value = String(state.currentEmployeeId);
  document.querySelector("#login-employee-choices").innerHTML = employees.map(employee => '<button type="button" role="option" data-login-account-role="employee" data-login-account-id="' + employee.id + '"><strong>' + escapeHtml(employee.name) + '</strong><small>Medewerker · ' + escapeHtml(employee.client) + '</small></button>').join("");
  updateLoginEmployeePreview();
}

function closeLoginAccountPanels() {
  document.querySelectorAll(".account-choice-panel").forEach(panel => { panel.hidden = true; });
  document.querySelectorAll("[data-account-picker-trigger]").forEach(trigger => trigger.setAttribute("aria-expanded", "false"));
}

function toggleLoginAccountPanel(role) {
  const trigger = document.querySelector('#login-' + role + '-trigger');
  const panel = document.querySelector('#login-' + role + '-choices');
  if (!trigger || !panel) return;
  const willOpen = panel.hidden;
  closeLoginAccountPanels();
  panel.hidden = !willOpen;
  trigger.setAttribute("aria-expanded", willOpen ? "true" : "false");
}

// The session is the only trustworthy source for *who you are*. The demo
// catalogue may not contain the authenticated account at all, and
// currentEmployee() then falls back to the first active colleague -- which is
// how "unknown" turned into someone else's name above your screen. Showing no
// name is acceptable; showing a colleague's name is not.
function authenticatedIdentityName() {
  if (authRuntime.mode !== "auth" || !authRuntime.authenticated) return "";
  return String(authRuntime.identityName || "");
}

function profileMatchesSession(profile) {
  const sessionEmail = String(authRuntime.identityEmail || "").toLowerCase();
  if (!sessionEmail) return true;
  return String(profile && profile.email || "").toLowerCase() === sessionEmail;
}

function profileForRole(role) {
  const sessionName = authenticatedIdentityName();
  const sessionProfile = base => {
    if (!sessionName) return base;
    if (base && profileMatchesSession(base)) return base;
    // Keep the role label and home view; replace only the identity.
    const label = role === "admin" ? roleProfiles.admin.label : roleProfiles.employee.label;
    const home = role === "admin" ? roleProfiles.admin.home : roleProfiles.employee.home;
    return {
      initials: initials(sessionName),
      name: sessionName,
      email: String(authRuntime.identityEmail || ""),
      photo: "",
      label,
      home
    };
  };

  if (role === "admin") {
    const admin = currentAdmin();
    if (!admin) return sessionName ? sessionProfile(null) : null;
    return sessionProfile({ initials: initials(admin.name), name: admin.name, email: admin.email, photo: admin.photo || "", label: roleProfiles.admin.label, home: roleProfiles.admin.home });
  }
  const employee = currentEmployee();
  if (!employee) return sessionName ? sessionProfile(null) : null;
  return sessionProfile({
    initials: initials(employee.name),
    name: employee.name,
    email: employee.email,
    photo: employee.photo || "",
    label: roleProfiles.employee.label,
    home: roleProfiles.employee.home
  });
}

function statusPill(status) {
  const info = statusLabels[status] || [status, "status-concept"];
  return '<span class="status-pill ' + info[1] + '">' + escapeHtml(info[0]) + "</span>";
}

function invoiceStatusInfo(record) {
  if (record.invoiceStatus === "simulated") return ["Verzending gecontroleerd", "status-sent"];
  if (record.invoiceStatus === "ready") return ["Factuur klaar", "status-ready"];
  if (record.timesheetStatus === "submitted") return ["Urencontrole nodig", "status-submitted"];
  if (record.timesheetStatus === "correction") return ["Correctie nodig", "status-correction"];
  return ["Nog niet ingediend", "status-concept"];
}

function invoiceStatusPill(record) {
  const info = invoiceStatusInfo(record);
  return '<span class="status-pill ' + info[1] + '">' + info[0] + "</span>";
}

function isValidEmail(value) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/i.test(String(value).trim());
}

function templateValues(employee, invoiceNumber, periodKey) {
  const period = periodFromKey(periodKey || currentPeriod().key);
  const record = recordFor(employee.id, period.key);
  const actualHours = totalEntries(record.entries);
  return {
    medewerker: employee.name,
    klant: employee.client,
    broker: employee.broker,
    maand: period.month,
    jaar: period.year,
    uren: hoursFormat.format(actualHours),
    factuurnummer: invoiceNumber,
    overeenkomstnummer: employee.agreementNumber || "Niet van toepassing"
  };
}

function formatTemplate(template, employee, invoiceNumber, periodKey) {
  const values = templateValues(employee, invoiceNumber, periodKey);
  return String(template).replace(/\{([a-z]+)\}/gi, (match, key) => values[key] === undefined ? match : values[key]);
}

function periodKeyFromControls(monthSelector, yearSelector) {
  const month = document.querySelector(monthSelector);
  const year = document.querySelector(yearSelector);
  if (!month || !year) return "";
  const yearValue = String(year.value || "").trim();
  const monthValue = String(month.value || "").trim();
  if (!/^\d{4}$/.test(yearValue) || !/^(0[1-9]|1[0-2])$/.test(monthValue)) return "";
  return yearValue + "-" + monthValue;
}

function syncPeriodControls(monthSelector, yearSelector, periodKey) {
  const parsed = parsePeriodKey(periodKey);
  const month = document.querySelector(monthSelector);
  const year = document.querySelector(yearSelector);
  if (!parsed || !month || !year) return;
  const monthValue = String(parsed.monthIndex + 1).padStart(2, "0");
  month.value = monthValue;
  if (month.tagName === "BUTTON") {
    month.textContent = MONTH_NAMES[parsed.monthIndex].charAt(0).toUpperCase() + MONTH_NAMES[parsed.monthIndex].slice(1);
    document.querySelectorAll('[data-month-control="' + monthSelector + '"]').forEach(button => {
      const active = button.dataset.periodMonth === monthValue;
      button.classList.toggle("is-active", active);
      button.setAttribute("aria-pressed", String(active));
    });
  }
  year.value = String(parsed.year).padStart(4, "0");
}

function closeMonthChoicePanels(exceptId = "") {
  document.querySelectorAll("[data-month-picker-trigger]").forEach(trigger => {
    const panelId = trigger.dataset.monthPickerTrigger;
    if (panelId === exceptId) return;
    const panel = document.getElementById(panelId);
    if (panel) panel.hidden = true;
    trigger.setAttribute("aria-expanded", "false");
  });
}

function toggleMonthChoicePanel(trigger) {
  const panelId = trigger.dataset.monthPickerTrigger;
  const panel = document.getElementById(panelId);
  if (!panel) return;
  const open = panel.hidden;
  closeMonthChoicePanels(open ? panelId : "");
  panel.hidden = !open;
  trigger.setAttribute("aria-expanded", String(open));
}

function applyPeriodControls(monthSelector, yearSelector, customerTimesheet = false) {
  const periodKey = periodKeyFromControls(monthSelector, yearSelector);
  if (customerTimesheet) document.querySelector("#customer-timesheet-file").value = "";
  if (!periodKey || !setPeriod(periodKey)) {
    syncPeriodControls(monthSelector, yearSelector, currentPeriod().key);
    toast(customerTimesheet ? "Kies eerst een geldige maand en een viercijferig jaar." : "Kies een geldige maand en een viercijferig jaar.");
  }
}

function renderPeriodHeadings() {
  const period = currentPeriod();
  document.querySelector("#period-label").textContent = period.label;
  document.querySelector("#period-picker").value = period.key;
  syncPeriodControls("#period-month-picker", "#period-year-picker", period.key);
  document.querySelector("#workflow-period-title").textContent = "Vier procesfasen voor " + period.month + " " + period.year;
  document.querySelector("#timesheet-period-title").textContent = period.label;
  document.querySelector("#invoice-period-title").textContent = "Facturen";
  document.querySelector("#employee-period-label").textContent = period.month + " " + period.year;
}

// De laatst toegepaste modus, zodat de merk-opmaak alleen bij een echte
// wisseling opnieuw wordt gezet en niet bij elke hertekening.
let vorigeModus = null;

function applyTheme() {
  const choice = state.preferences && state.preferences.theme ? state.preferences.theme : "light";
  let resolved = choice;
  if (choice === "system") {
    resolved = window.matchMedia && window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
  }
  document.documentElement.dataset.theme = resolved;
  document.documentElement.dataset.themeChoice = choice;
  // Het logo hangt aan de modus: donker woordmerk op een lichte topbalk, wit op
  // een donkere. Zonder dit bleef de vorige versie staan tot de app zichzelf
  // helemaal opnieuw tekende.
  //
  // Alleen bij een echte wisseling. applyTheme() draait bij elke hertekening, en
  // de merk-opmaak opnieuw toepassen terwijl er niets veranderd is, is werk dat
  // niets oplevert -- het zet alleen dezelfde afbeelding en dezelfde kleuren
  // terug.
  if (vorigeModus !== resolved) {
    vorigeModus = resolved;
    if (typeof applyOrganizationBranding === "function") applyOrganizationBranding();
  }
  const meta = document.querySelector('meta[name="theme-color"]');
  if (meta) meta.content = resolved === "dark" ? "#09131f" : normalizedBrandColor(state.settings.brandPrimary, "#0d1b38");
}

function greetingForNow() {
  let hour = new Date().getHours();
  try {
    hour = Number(new Intl.DateTimeFormat("nl-NL", { hour: "2-digit", hour12: false, timeZone: "Europe/Amsterdam" }).format(new Date()).replace(/\D/g, ""));
  } catch {
    hour = new Date().getHours();
  }
  if (hour >= 5 && hour < 12) return "Goedemorgen";
  if (hour >= 12 && hour < 18) return "Goedemiddag";
  return "Goedenavond";
}

function renderProfileChrome() {
  if (!state.currentRole) return;
  const profile = profileForRole(state.currentRole);
  if (!profile) return;
  applyAvatar(document.querySelector("#workspace-avatar"), profile.name, profile.photo);
  applyAvatar(document.querySelector("#topbar-avatar"), profile.name, profile.photo);
  applyAvatar(document.querySelector("#profile-menu-avatar"), profile.name, profile.photo);
  document.querySelector("#workspace-name").textContent = profile.name;
  document.querySelector("#workspace-role").textContent = profile.label;
  document.querySelector("#profile-menu-name").textContent = profile.name;
  document.querySelector("#profile-menu-role").textContent = profile.label;
}

function customerTimesheetNeedsEmployeeAction(status) {
  return ["missing", "draft", "resubmit"].includes(status);
}

function renderEmployeeCustomerTimesheet(record, employee, period) {
  const card = document.querySelector("#employee-customer-timesheet-card");
  if (!card) return;
  card.hidden = employee.customerTimesheetExpected === false;
  if (card.hidden) return;
  const documentRecord = customerTimesheetFor(record);
  const status = customerTimesheetStatusLabels[documentRecord.status] || customerTimesheetStatusLabels.missing;
  const needsAction = customerTimesheetNeedsEmployeeAction(documentRecord.status);
  const openButton = document.querySelector("#employee-customer-timesheet-open");
  const skipButton = document.querySelector("#employee-customer-timesheet-skip");
  let title = "Klanturenstaat staat nog open";
  let note = "Upload de officiële klanturenstaat of registreer dat je deze al rechtstreeks hebt gemaild.";
  if (documentRecord.status === "draft") {
    title = "Concept staat klaar, maar is nog niet ingediend";
    note = "Dien het opgeslagen document in bij Backoffice of registreer dat je het al rechtstreeks hebt gemaild.";
  } else if (documentRecord.status === "resubmit") {
    title = "Nieuwe klanturenstaat nodig";
    note = documentRecord.reviewNote || "Backoffice heeft gevraagd om het juiste of definitieve document opnieuw te uploaden.";
  } else if (documentRecord.status === "received") {
    title = "Klanturenstaat is ingediend";
    note = "Backoffice heeft het document ontvangen en controleert het.";
  } else if (documentRecord.status === "approved") {
    title = "Klanturenstaat is goedgekeurd";
    note = "Backoffice heeft het document gecontroleerd. Voor jou is deze stap afgerond.";
  } else if (["sent", "sent_to_broker"].includes(documentRecord.status)) {
    title = "Klanturenstaat is verwerkt";
    note = "Backoffice heeft ook de brokerroute gecontroleerd.";
  } else if (documentRecord.status === "skipped") {
    title = "Als rechtstreeks gemaild geregistreerd";
    note = (documentRecord.skippedReason || "De klanturenstaat is al rechtstreeks naar Path Backoffice gemaild.") + (documentRecord.skippedAt ? " · " + documentRecord.skippedAt : "");
  }
  document.querySelector("#employee-customer-timesheet-period").textContent = period.label;
  document.querySelector("#employee-customer-timesheet-title").textContent = title;
  document.querySelector("#employee-customer-timesheet-note").textContent = note;
  const statusElement = document.querySelector("#employee-customer-timesheet-status");
  statusElement.className = "status-pill " + status[1];
  statusElement.textContent = status[0];
  card.classList.toggle("is-open", needsAction);
  card.classList.toggle("is-complete", !needsAction);
  openButton.textContent = needsAction ? "Klanturenstaat openen" : "Details bekijken";
  skipButton.hidden = !needsAction && documentRecord.status !== "skipped";
  skipButton.textContent = documentRecord.status === "skipped" ? "Alsnog uploaden" : "Al rechtstreeks gemaild";
}

function renderEmployeeDashboard() {
  const employee = currentEmployee();
  const employeeId = Number(employee.id);
  const selectedPeriodAtRender = currentPeriod().key;
  const needsInitialHydration = API_ENABLED && authRuntime.mode === "auth" && state.currentRole === "employee" && !readApiRuntime.employeeOpenTasksHydrated;
  if (needsInitialHydration && !readApiRuntime.employeeOpenTasksSyncInFlight) {
    refreshEmployeeOpenTasksReadApi(true)
      .then(() => {
        readApiRuntime.employeeOpenTasksHydrated = true;
      })
      .catch(() => {
        readApiRuntime.employeeOpenTasksHydrated = true;
      })
      .finally(() => {
        const stillEmployeeView = document.querySelector("#view-employee-dashboard")?.classList.contains("is-active");
        const stillSameEmployee = Number(currentEmployee().id) === employeeId;
        const stillSamePeriod = currentPeriod().key === selectedPeriodAtRender;
        if (stillEmployeeView && stillSameEmployee && stillSamePeriod) renderEmployeeDashboard();
      });
  }
  refreshEmployeeOpenTasksReadApi(false).then(changed => {
    if (!changed) return;
    const stillEmployeeView = document.querySelector("#view-employee-dashboard")?.classList.contains("is-active");
    const stillSameEmployee = Number(currentEmployee().id) === employeeId;
    const stillSamePeriod = currentPeriod().key === selectedPeriodAtRender;
    if (stillEmployeeView && stillSameEmployee && stillSamePeriod) renderEmployeeDashboard();
  }).catch(() => null);
  const record = recordFor(employee.id);
  const period = currentPeriod();
  const total = totalEntries(record.entries);
  const absence = Number(record.leave || 0) + Number(record.sick || 0);
  const accounted = total + absence;
  const difference = Math.round((accounted - record.contractHours) * 10) / 10;
  const progress = record.contractHours > 0 ? Math.min(100, Math.round(accounted / record.contractHours * 100)) : 0;
  const firstName = employee.name.split(/\s+/)[0];
  const status = statusLabels[record.timesheetStatus] || statusLabels.draft;
  const customerDocument = customerTimesheetFor(record);
  const customerTimesheetOpen = employee.customerTimesheetExpected !== false && customerTimesheetNeedsEmployeeAction(customerDocument.status);
  let next = "Vul je uren in en dien alleen deze maand in.";
  let action = "Uren verder invullen";
  let note = "Nog niet ingediend";
  if (record.timesheetStatus === "correction") {
    const correction = activeCorrection(record) || latestCorrection(record);
    next = correction
      ? "Je uren zijn teruggestuurd. Reden: " + correction.message
      : "Je uren zijn teruggestuurd. Pas ze aan en dien de maand opnieuw in.";
    action = "Correctie openen";
    note = "Actie nodig";
  }
  if (record.timesheetStatus === "submitted") {
    next = "Je uren zijn ingediend en wachten op controle door Gio of Joyce.";
    action = "Ingediende uren bekijken";
    note = "Wacht op controle";
  }
  if (record.timesheetStatus === "approved") {
    next = customerTimesheetOpen
      ? "Je uren zijn goedgekeurd, maar je klanturenstaat staat nog open."
      : "Je uren zijn goedgekeurd. Voor deze maand hoef je niets meer te doen.";
    action = customerTimesheetOpen ? "Klanturenstaat aanleveren" : "Goedgekeurde uren bekijken";
    note = customerTimesheetOpen ? "Uren afgerond · klanturenstaat open" : "Afgerond";
  }
  const openMonthSummaries = employeeOpenMonthSummaries(employee.id, period.key);
  const employeeOpenActions = openMonthSummaries.flatMap(item => item.actions);
  const nextOpenMonth = openMonthSummaries[0] || null;
  const nextOpenAction = nextOpenMonth?.actions[0] || null;
  const openHoursCount = employeeOpenActions.filter(item => item.type === "hours").length;
  const openCustomerCount = employeeOpenActions.filter(item => item.type === "customer").length;
  if (nextOpenMonth && nextOpenAction) {
    next = nextOpenAction.description + " voor " + nextOpenMonth.period.label + ".";
    action = nextOpenAction.button;
  } else {
    next = "Alles voor deze maand is afgerond.";
    action = "Uren bekijken";
    note = "Afgerond";
  }
  const dashboardBadge = document.querySelector("#employee-dashboard-count");
  if (dashboardBadge) {
    const openCount = employeeOpenActions.length;
    dashboardBadge.textContent = String(openCount);
    dashboardBadge.hidden = openCount === 0;
    if (openCount > 0) dashboardBadge.setAttribute("aria-label", openCount + " open actie" + (openCount === 1 ? "" : "s") + " op je dashboard");
    else dashboardBadge.removeAttribute("aria-label");
  }
  document.querySelector("#employee-dashboard-greeting").textContent = greetingForNow() + ", " + firstName;
  document.querySelector("#employee-dashboard-next").textContent = next;
  document.querySelector("#employee-dashboard-next-label").textContent = nextOpenAction ? "Volgende actie" : "Deze maand";
  document.querySelector("#employee-dashboard-next-meta").textContent = nextOpenMonth
    ? nextOpenMonth.period.label + " · actie 1 van " + employeeOpenActions.length
    : period.label + " · alles afgerond";
  const dashboardAction = document.querySelector("#employee-dashboard-action");
  dashboardAction.textContent = action;
  if (nextOpenMonth && nextOpenAction) {
    dashboardAction.dataset.employeeActionPeriod = nextOpenMonth.periodKey;
    dashboardAction.dataset.employeeActionType = nextOpenAction.type;
  } else {
    delete dashboardAction.dataset.employeeActionPeriod;
    delete dashboardAction.dataset.employeeActionType;
  }
  const allActionsButton = document.querySelector("#employee-dashboard-all-actions");
  allActionsButton.hidden = employeeOpenActions.length === 0;
  allActionsButton.textContent = "Bekijk alle " + employeeOpenActions.length + " open " + (employeeOpenActions.length === 1 ? "actie" : "acties");
  document.querySelector(".employee-hero").classList.toggle("is-complete", employeeOpenActions.length === 0);
  document.querySelector("#employee-dashboard-period").textContent = period.label;
  document.querySelector("#employee-dashboard-hours").textContent = hoursFormat.format(accounted) + " uur";
  document.querySelector("#employee-dashboard-contract").textContent = "van " + hoursFormat.format(record.contractHours) + " contracturen";
  document.querySelector("#employee-dashboard-progress").style.width = progress + "%";
  document.querySelector("#employee-open-task-total").textContent = employeeOpenActions.length + " open " + (employeeOpenActions.length === 1 ? "actie" : "acties");
  document.querySelector("#employee-open-task-months").textContent = employeeOpenActions.length ? employeeOpenMonthEquation(openMonthSummaries) : "Alles afgerond";
  document.querySelector("#employee-open-task-owners").textContent = "Urenregistraties " + openHoursCount + " + klanturenstaten " + openCustomerCount + " = " + employeeOpenActions.length;
  document.querySelector("#employee-dashboard-status").textContent = status[0];
  document.querySelector("#employee-dashboard-status-note").textContent = note;
  document.querySelector("#employee-dashboard-billable").textContent = hoursFormat.format(total);
  document.querySelector("#employee-dashboard-absence").textContent = hoursFormat.format(absence);
  document.querySelector("#employee-dashboard-difference").textContent = (difference > 0 ? "+" : "") + hoursFormat.format(difference);

  const dashboardCorrection = document.querySelector("#employee-dashboard-correction");
  const openCorrection = activeCorrection(record);
  dashboardCorrection.hidden = !openCorrection;
  if (openCorrection) {
    document.querySelector("#employee-dashboard-correction-message").textContent = openCorrection.message;
    document.querySelector("#employee-dashboard-correction-meta").textContent = "Teruggestuurd door " + openCorrection.requestedBy + " · " + openCorrection.requestedAt;
  }

  renderEmployeeCustomerTimesheet(record, employee, period);

  const openOverview = document.querySelector('#employee-open-overview');
  const openOverviewCount = document.querySelector('#employee-open-overview-count');
  const openOverviewList = document.querySelector('#employee-open-overview-list');
  if (openOverview && openOverviewCount && openOverviewList) {
    openOverview.hidden = openMonthSummaries.length === 0;
    openOverviewCount.textContent = openMonthSummaries.length + ' open maand' + (openMonthSummaries.length === 1 ? '' : 'en');
    const openOverviewNote = document.querySelector('#employee-open-overview-note');
    if (openOverviewNote && nextOpenMonth && nextOpenAction) {
      openOverviewNote.textContent = 'Begin met ' + nextOpenAction.label.toLowerCase() + ' voor ' + nextOpenMonth.period.label + '.';
    }
    openOverviewList.innerHTML = openMonthSummaries.map((item) => {
      const monthBodyId = 'employee-open-month-body-' + item.periodKey;
      const actionCount = item.actions.length;
      // Every month starts collapsed; a render never re-expands a month the medewerker chose to open or close.
      const expanded = false;
      return '<section class="employee-open-month' + (item.current ? ' is-current' : '') + '" data-employee-open-month="' + item.periodKey + '">' +
        '<button class="employee-open-month-heading" type="button" data-employee-open-month-toggle="' + item.periodKey + '" aria-expanded="' + (expanded ? 'true' : 'false') + '" aria-controls="' + monthBodyId + '">' +
          '<span class="employee-open-month-heading-copy"><strong>' + escapeHtml(item.period.label) + ' · ' + actionCount + ' open ' + (actionCount === 1 ? 'actie' : 'acties') + '</strong><small>' + escapeHtml(item.notes) + '</small></span>' +
          '<span class="employee-open-month-heading-side"><span class="status-pill ' + item.tone + '">' + escapeHtml(item.label) + '</span><span class="employee-open-month-chevron" aria-hidden="true"></span></span>' +
        '</button>' +
        '<div class="employee-open-month-body" id="' + monthBodyId + '"' + (expanded ? '' : ' hidden') + '><div class="employee-open-action-list">' + item.actions.map(action =>
          '<div class="employee-open-action-row" data-employee-action-row="' + action.type + '">' +
            '<div class="employee-open-action-copy"><span>' + escapeHtml(action.category) + '</span><strong>' + escapeHtml(action.label) + '</strong><small>' + escapeHtml(action.description) + '</small></div>' +
            '<button class="small-button" type="button" data-employee-open-action="' + action.type + '" data-period-key="' + item.periodKey + '">' + escapeHtml(action.button) + '</button>' +
          '</div>').join('') + '</div></div>' +
      '</section>';
    }).join('');
  }

  const history = Object.keys(state.records)
    .sort((left, right) => right.localeCompare(left))
    .filter(key => state.records[key] && state.records[key][String(employee.id)])
    .slice(0, 6);
  const historyRows = history.map(key => {
    const historyRecord = recordFor(employee.id, key);
    const historyTotal = totalEntries(historyRecord.entries) + Number(historyRecord.leave || 0) + Number(historyRecord.sick || 0);
    const correction = latestCorrection(historyRecord);
    const historyNote = correction
      ? "Correctie door " + correction.requestedBy + " · " + correction.requestedAt
      : "Eigen urenregistratie";
    const currentLabel = key === currentCalendarPeriodKey() ? '<span class="employee-history-current">Huidige maand</span>' : '';
    return '<div class="employee-history-row"><div><strong>' + escapeHtml(periodFromKey(key).label) + currentLabel + '</strong><small>' + escapeHtml(historyNote) + '</small></div><div><strong>' + hoursFormat.format(historyTotal) + ' uur</strong><small>totaal verantwoord</small></div><div>' + statusPill(historyRecord.timesheetStatus) + '</div><button class="small-button" data-history-period="' + key + '">Open maand</button></div>';
  }).join("");
  document.querySelector("#employee-history").innerHTML = historyRows
    ? '<div class="employee-history-head" aria-hidden="true"><span>Maand</span><span>Uren</span><span>Status</span><span>Actie</span></div>' + historyRows
    : '<div class="dashboard-action-empty">Er zijn nog geen maanden beschikbaar.</div>';
}

function adminOpenTasks() {
  const tasks = [];
  openPeriodSummaries().forEach(summary => {
    const periodKey = summary.periodKey;
    const period = summary.period;
    activeEmployees()
      .filter(employee => !employee.startDate || employee.startDate.slice(0, 7) <= periodKey)
      .forEach(employee => {
        const record = recordFor(employee.id, periodKey);
        const documentRecord = customerTimesheetFor(record);
        const base = { employee, record, period, periodKey, isOverdue: summary.isOverdue };
        if (record.timesheetStatus === "submitted") {
          tasks.push(Object.assign({}, base, { id: "hours-review-" + periodKey + "-" + employee.id, type: "hours-review", category: "Uren", actionable: true, priority: 1, title: "Uren controleren", note: hoursFormat.format(totalEntries(record.entries)) + " declarabele uren wachten op goedkeuring." }));
        } else if (record.timesheetStatus === "correction") {
          tasks.push(Object.assign({}, base, { id: "hours-correction-" + periodKey + "-" + employee.id, type: "hours-correction", category: "Uren", actionable: false, priority: 2, title: "Wacht op aangepaste uren", note: "De medewerker moet de gevraagde correctie nog opnieuw indienen." }));
        } else if (record.timesheetStatus === "draft") {
          tasks.push(Object.assign({}, base, { id: "hours-draft-" + periodKey + "-" + employee.id, type: "hours-draft", category: "Uren", actionable: false, priority: 3, title: "Uren nog niet ingediend", note: "De medewerker moet deze maand nog indienen." }));
        }
        if (employee.customerTimesheetExpected !== false) {
          if (documentRecord.status === "received") {
            tasks.push(Object.assign({}, base, { id: "customer-review-" + periodKey + "-" + employee.id, type: "customer-review", category: "Klanturenstaat", actionable: true, priority: 2, title: "Klanturenstaat controleren", note: "Het ontvangen document wacht op controle door Backoffice." }));
          } else if (documentRecord.status === "approved" && employee.customerTimesheetBrokerEnabled !== false) {
            tasks.push(Object.assign({}, base, { id: "customer-broker-" + periodKey + "-" + employee.id, type: "customer-broker", category: "Klanturenstaat", actionable: true, priority: 3, title: "Brokerroute controleren", note: "De klanturenstaat is goedgekeurd en staat klaar voor de brokerroute." }));
          } else if (["missing", "draft", "resubmit"].includes(documentRecord.status)) {
            const documentStatus = (customerTimesheetStatusLabels[documentRecord.status] || customerTimesheetStatusLabels.missing)[0];
            tasks.push(Object.assign({}, base, { id: "customer-waiting-" + periodKey + "-" + employee.id, type: "customer-waiting", category: "Klanturenstaat", actionable: false, priority: 4, title: documentStatus, note: documentRecord.status === "resubmit" ? "De medewerker moet een nieuw document uploaden." : "De officiële klanturenstaat is nog niet bij Backoffice ingediend." }));
          }
        }
        if (["approved", "invoiced"].includes(record.timesheetStatus) && (record.invoiceStatus === "ready" || record.payrollStatus === "ready")) {
          tasks.push(Object.assign({}, base, { id: "invoice-delivery-" + periodKey + "-" + employee.id, type: "invoice-delivery", category: "Factuur", actionable: true, priority: 4, title: "Verzending controleren", note: "De afzonderlijke factuur- en salarisroutes staan klaar voor controle." }));
        }
      });
  });
  return tasks.sort((left, right) => left.periodKey.localeCompare(right.periodKey) || Number(right.actionable) - Number(left.actionable) || left.priority - right.priority || left.employee.name.localeCompare(right.employee.name));
}

function employeeOpenTasks(employeeId) {
  return adminOpenTasks().filter(task => Number(task.employee.id) === Number(employeeId));
}

function employeeOpenMonthSummaries(employeeId, currentPeriodKey) {
  const employee = employeeById(employeeId);
  if (!employee) return [];

  return Object.keys(state.records)
    .filter(key => parsePeriodKey(key))
    .sort()
    .map(key => {
      const historyRecord = recordFor(employee.id, key);
      if (!employeeStartedByPeriodEnd(employee, key)) return null;
      // De actuele kalendermaand is ook zonder geboekte uren een echte
      // werkmaand. Historische en toekomstige lege maanden blijven verborgen.
      if (key !== currentPeriodKey && !recordHasPeriodActivity(historyRecord)) return null;
      const customerRecord = customerTimesheetFor(historyRecord);
      const actions = [];

      if (historyRecord.timesheetStatus === 'draft') {
        actions.push({ type: 'hours', category: 'Urenregistratie', label: 'Uren indienen', description: 'Controleer je uren en dien deze maand in.', button: 'Open uren', tone: 'status-concept' });
      } else if (historyRecord.timesheetStatus === 'correction') {
        actions.push({ type: 'hours', category: 'Urenregistratie', label: 'Correctie indienen', description: activeCorrection(historyRecord)?.message || 'Pas je uren aan en dien deze maand opnieuw in.', button: 'Open correctie', tone: 'status-warning' });
      }

      if (employee.customerTimesheetExpected !== false) {
        if (customerRecord.status === 'missing' || customerRecord.status === 'draft') {
          actions.push({ type: 'customer', category: 'Document van de klant', label: 'Klanturenstaat uploaden', description: customerRecord.status === 'draft' ? 'Dien het opgeslagen document in bij Backoffice.' : 'Lever de officiële klanturenstaat aan bij Backoffice.', button: 'Open document', tone: 'status-concept' });
        } else if (customerRecord.status === 'resubmit') {
          actions.push({ type: 'customer', category: 'Document van de klant', label: 'Klanturenstaat opnieuw uploaden', description: customerRecord.reviewNote || 'Upload het juiste of definitieve document opnieuw.', button: 'Open verzoek', tone: 'status-warning' });
        }
      }

      if (!actions.length) return null;

      const hourAction = actions.find(action => action.type === 'hours');
      const customerAction = actions.find(action => action.type === 'customer');
      const notes = [];
      if (hourAction) notes.push(hourAction.label);
      if (customerAction) notes.push(customerAction.label);

      let label = actions.length === 1 ? actions[0].label : actions.length + ' acties voor jou';
      let tone = actions.some(action => action.tone === 'status-warning') ? 'status-warning' : 'status-concept';

      return {
        periodKey: key,
        period: periodFromKey(key),
        label,
        tone,
        notes: notes.join(' · '),
        current: key === currentPeriodKey,
        actions,
      };
    })
    .filter(Boolean);
}

function employeeOpenMonthEquation(openMonthSummaries) {
  if (!openMonthSummaries.length) return 'Alles afgerond';
  const equation = openMonthSummaries
    .map(item => item.period.label.split(' ')[0] + ' ' + item.actions.length)
    .join(' + ');
  const total = openMonthSummaries.reduce((sum, item) => sum + item.actions.length, 0);
  return equation + ' = ' + total;
}

function adminTaskAction(task) {
  if (task.type === "hours-review") return '<button class="small-button" data-review="' + task.employee.id + '" data-period-key="' + task.periodKey + '">Uren controleren</button>';
  if (task.type === "customer-review") return '<button class="small-button" data-review-customer-timesheet="' + task.employee.id + '" data-period-key="' + task.periodKey + '">Document controleren</button>';
  if (task.type === "customer-broker") return '<button class="small-button" data-send-customer-timesheet="' + task.employee.id + '" data-period-key="' + task.periodKey + '">Brokerroute controleren</button>';
  if (task.type === "invoice-delivery") return '<button class="small-button" data-admin-task-invoice="' + task.employee.id + '" data-period-key="' + task.periodKey + '">Verzending controleren</button>';
  if (task.type === "customer-waiting") return '<button class="small-button" data-remind-customer-timesheet="' + task.employee.id + '" data-period-key="' + task.periodKey + '">Herinner medewerker</button>';
  return '<button class="small-button" data-admin-hours-detail="' + task.employee.id + '" data-period-key="' + task.periodKey + '">Medewerkerstatus bekijken</button>';
}

function groupAdminTasksByMonth(tasks) {
  const groups = new Map();
  tasks.forEach(task => {
    if (!groups.has(task.periodKey)) groups.set(task.periodKey, []);
    groups.get(task.periodKey).push(task);
  });
  return [...groups.entries()]
    .sort((left, right) => left[0].localeCompare(right[0]))
    .map(([periodKey, monthTasks]) => ({ periodKey, period: periodFromKey(periodKey), tasks: monthTasks }));
}

function adminTaskMonthEquation(tasks, includeTotal = true) {
  if (!tasks.length) return "Geen open acties";
  const equation = groupAdminTasksByMonth(tasks)
    .map(group => group.period.label.split(" ")[0] + " " + group.tasks.length)
    .join(" + ");
  return includeTotal ? equation + " = " + tasks.length : equation;
}

function renderAdminTaskQueue() {
  const panel = document.querySelector("#admin-task-panel");
  if (!panel) return;
  const tasks = adminOpenTasks();
  const actionable = tasks.filter(task => task.actionable);
  const waiting = tasks.filter(task => !task.actionable);
  const filter = state.adminTaskFilter || "all";
  const content = document.querySelector("#admin-task-content");
  const toggle = document.querySelector("#admin-task-panel-toggle");
  const expanded = state.adminTaskPanelExpanded === true;
  if (content) content.hidden = !expanded;
  if (toggle) {
    toggle.setAttribute("aria-expanded", String(expanded));
    toggle.textContent = expanded ? "Overzicht inklappen" : "Overzicht openen";
  }
  const filtered = filter === "all" ? tasks : filter === "waiting" ? waiting : actionable;
  const filteredMonthGroups = groupAdminTasksByMonth(filtered);
  const taskMonths = new Set(tasks.map(task => task.periodKey)).size;
  const taskDossiers = new Set(tasks.map(task => task.periodKey + ":" + task.employee.id)).size;
  const taskTitle = document.querySelector("#admin-task-title");
  if (taskTitle) taskTitle.textContent = filter === "actionable" ? "Acties bij Backoffice per maand" : filter === "waiting" ? "Wacht op medewerkers per maand" : "Alle open acties per maand";
  document.querySelector("#admin-task-summary").textContent = !tasks.length
    ? "Alles is afgehandeld."
    : filter === "actionable"
      ? actionable.length + " acties die Backoffice nu kan oppakken, verdeeld over " + filteredMonthGroups.length + " " + (filteredMonthGroups.length === 1 ? "maand" : "maanden") + "."
      : filter === "waiting"
        ? waiting.length + " acties waarvoor medewerkers eerst iets moeten indienen of corrigeren, verdeeld over " + filteredMonthGroups.length + " " + (filteredMonthGroups.length === 1 ? "maand" : "maanden") + "."
        : tasks.length + " open " + (tasks.length === 1 ? "actie" : "acties") + " in " + taskDossiers + " " + (taskDossiers === 1 ? "dossier" : "dossiers") + ": " + adminTaskMonthEquation(tasks) + ". Backoffice kan " + actionable.length + " oppakken; " + waiting.length + " " + (waiting.length === 1 ? "wacht" : "wachten") + " op medewerkers. Iedere regel hieronder is één actie.";
  document.querySelector("#admin-task-filters").innerHTML = [
    ["all", "Alle acties", tasks.length],
    ["actionable", "Bij Backoffice", actionable.length],
    ["waiting", "Bij medewerkers", waiting.length]
  ].map(item => '<button class="' + (filter === item[0] ? "is-active" : "") + '" data-admin-task-filter="' + item[0] + '">' + item[1] + ' · ' + item[2] + '</button>').join("");
  const renderTaskRow = task => '<article class="admin-task-row ' + (task.actionable ? "is-actionable" : "is-waiting") + '" data-admin-task-row="' + task.id + '">' +
      '<div class="admin-task-kind"><span>' + escapeHtml(task.category) + '</span><strong>' + escapeHtml(task.title) + '</strong></div>' +
      '<div class="admin-task-person"><strong>' + escapeHtml(task.employee.name) + '</strong><small>' + escapeHtml(task.employee.client + " · " + task.employee.broker) + '</small></div>' +
      '<div class="admin-task-note"><span class="status-pill ' + (task.actionable ? "status-submitted" : "status-concept") + '">' + (task.actionable ? "Actie bij Backoffice" : "Actie bij medewerker") + '</span><small>' + escapeHtml(task.note) + '</small></div>' +
      '<div class="admin-task-action">' + adminTaskAction(task) + '</div>' +
    '</article>';
  document.querySelector("#admin-task-list").innerHTML = filteredMonthGroups.map(group => {
    const monthActionable = group.tasks.filter(task => task.actionable);
    const monthWaiting = group.tasks.filter(task => !task.actionable);
    const timing = group.tasks.some(task => task.isOverdue) ? "Eerdere maand · nog niet afgerond" : "Huidige maand";
    const ownerSummary = filter === "actionable"
      ? monthActionable.length + " bij Backoffice"
      : filter === "waiting"
        ? monthWaiting.length + " bij " + (monthWaiting.length === 1 ? "medewerker" : "medewerkers")
        : monthActionable.length + " bij Backoffice · " + monthWaiting.length + " bij " + (monthWaiting.length === 1 ? "medewerker" : "medewerkers");
    const ownerGroups = [];
    if (monthActionable.length) ownerGroups.push('<div class="admin-task-owner-group"><div class="admin-task-owner-heading is-actionable">Nu doen door Backoffice · ' + monthActionable.length + '</div>' + monthActionable.map(renderTaskRow).join("") + '</div>');
    if (monthWaiting.length) ownerGroups.push('<div class="admin-task-owner-group"><div class="admin-task-owner-heading is-waiting">Wacht op medewerkers · ' + monthWaiting.length + '</div>' + monthWaiting.map(renderTaskRow).join("") + '</div>');
    const monthStateKey = filter + ":" + group.periodKey;
    const monthSignature = group.tasks.map(task => task.id).join("|");
    const savedMonthState = state.adminTaskMonthState[monthStateKey];
    const hasCurrentExpansionOverride = savedMonthState && savedMonthState.signature === monthSignature;
    const isExpanded = hasCurrentExpansionOverride ? savedMonthState.expanded : false;
    const monthBodyId = "admin-task-month-body-" + group.periodKey;
    return '<section class="admin-task-month" data-admin-task-month="' + group.periodKey + '">' +
      '<button class="admin-task-month-heading" type="button" data-admin-task-month-toggle="' + group.periodKey + '" data-admin-task-month-signature="' + escapeHtml(monthSignature) + '" aria-expanded="' + String(isExpanded) + '" aria-controls="' + monthBodyId + '"><span class="admin-task-month-heading-copy"><span>' + escapeHtml(timing) + '</span><strong>' + escapeHtml(group.period.label) + ' · ' + group.tasks.length + " open " + (group.tasks.length === 1 ? "actie" : "acties") + '</strong></span><span class="admin-task-month-heading-side"><small>' + escapeHtml(ownerSummary) + '</small><span class="admin-task-month-chevron" aria-hidden="true"></span></span></button>' +
      '<div class="admin-task-month-body" id="' + monthBodyId + '"' + (isExpanded ? "" : " hidden") + '>' + ownerGroups.join("") + '</div>' +
    '</section>';
  }).join("") || '<div class="dashboard-action-empty">' + (filter === "actionable" ? "Er ligt niets meer bij Backoffice." : filter === "waiting" ? "Er liggen geen acties bij medewerkers." : "Alle acties zijn afgerond.") + '</div>';
}

function actionableAdminTasks() {
  return adminOpenTasks().filter(task => task.actionable);
}

function orderedAdminWorkflowTasks() {
  const currentTasks = actionableAdminTasks();
  if (!adminTaskWorkflow) return currentTasks;
  
  // Always return tasks in chronological order (per period, then actionable, then priority, then name)
  // regardless of workflow history. This prevents illogical jumps to unrelated months/employees.
  const workflowTaskIds = new Set(adminTaskWorkflow.taskIds);
  return currentTasks;  // currentTasks is already chronologically sorted from adminOpenTasks()
}

function beginAdminTaskWorkflow(taskId) {
  const tasks = actionableAdminTasks();
  if (!tasks.some(task => task.id === taskId)) return false;
  adminTaskWorkflow = { taskIds: tasks.map(task => task.id), activeTaskId: taskId, completedCount: 0 };
  return true;
}

function modalTaskFormIsDirty() {
  return [...document.querySelectorAll("#modal-summary input, #modal-summary textarea")]
    .some(field => field.value !== field.defaultValue);
}

function renderModalTaskNavigation(taskId) {
  const navigation = document.querySelector("#modal-queue");
  const previous = document.querySelector("#modal-queue-previous");
  const next = document.querySelector("#modal-queue-next");
  if (!adminTaskWorkflow) {
    navigation.hidden = true;
    return;
  }
  const tasks = orderedAdminWorkflowTasks();
  const index = tasks.findIndex(task => task.id === taskId);
  if (index < 0) {
    navigation.hidden = true;
    return;
  }
  adminTaskWorkflow.activeTaskId = taskId;
  navigation.hidden = false;
  document.querySelector("#modal-queue-progress").textContent = "Actie " + (index + 1) + " van " + tasks.length + " bij Backoffice";
  const dirty = modalTaskFormIsDirty();
  document.querySelector("#modal-queue-note").textContent = dirty
    ? "Rond de wijziging af of annuleer eerst."
    : (adminTaskWorkflow.completedCount ? adminTaskWorkflow.completedCount + " afgehandeld in deze sessie · bladeren wijzigt niets." : "Vorige en volgende wijzigen niets.");
  previous.disabled = index === 0 || dirty;
  next.disabled = index === tasks.length - 1 || dirty;
}

function moveAdminTaskWorkflow(direction) {
  if (!adminTaskWorkflow || modalTaskFormIsDirty()) {
    if (modalTaskFormIsDirty()) toast("Rond de wijziging af of annuleer eerst; Vorige en Volgende slaan niets op.");
    return;
  }
  const tasks = orderedAdminWorkflowTasks();
  const index = tasks.findIndex(task => task.id === adminTaskWorkflow.activeTaskId);
  const target = tasks[index + direction];
  if (!target) return;
  openAdminTask(target.id, { continueWorkflow: true });
}

function showAdminTaskEmailBlocker(taskId, employee, periodKey, invalidAddresses, contextLabel) {
  const period = periodFromKey(periodKey);
  const invalidSender = invalidAddresses.some(item => item.kind === "sender");
  const summary = invalidAddresses.map(item => '<div><span>' + escapeHtml(item.name) + '</span><strong>' + escapeHtml(item.email || "Niet ingevuld") + '</strong></div>').join("") +
    '<div><span>Status</span><strong>Actie blijft open</strong></div>';
  showModal({
    label: "Actie geblokkeerd",
    title: employee.name + " · " + period.label,
    message: contextLabel + " kan pas worden afgerond nadat " + (invalidAddresses.length === 1 ? "dit e-mailadres is" : "deze e-mailadressen zijn") + " hersteld. Je kunt met Vorige en Volgende wel door de overige Backoffice-acties bladeren.",
    summary,
    secondary: invalidSender ? "E-mailinstellingen openen" : "Mailroute aanpassen",
    secondaryAction: () => {
      closeModal();
      if (invalidSender) showView("settings");
      else showEmployeeEditor(employee.id);
    },
    confirm: "Werkmodus sluiten",
    action: closeModal,
    adminTaskId: taskId
  });
  return true;
}

function finishAdminTaskAndContinue(taskId, mutate, toastMessage) {
  const workflowActive = Boolean(adminTaskWorkflow && adminTaskWorkflow.activeTaskId === taskId);
  const previousOrder = adminTaskWorkflow ? [...adminTaskWorkflow.taskIds] : actionableAdminTasks().map(task => task.id);
  const completedTask = actionableAdminTasks().find(task => task.id === taskId);
  mutate();
  persistState();
  renderAll();
  if (!workflowActive) {
    closeModal();
    toast(toastMessage);
    return;
  }
  adminTaskWorkflow.completedCount += 1;
  const remaining = actionableAdminTasks().filter(task => task.id !== taskId);
  if (!remaining.length) {
    const waiting = adminOpenTasks().filter(task => !task.actionable);
    showModal({
      label: "Werkvoorraad afgerond",
      title: "Alle Backoffice-acties zijn afgehandeld",
      message: waiting.length
        ? waiting.length + " " + (waiting.length === 1 ? "actie wacht" : "acties wachten") + " nog op medewerkers."
        : "Er staat voor niemand meer een actie open.",
      summary: '<div><span>Afgehandeld in deze sessie</span><strong>' + adminTaskWorkflow.completedCount + '</strong></div><div><span>Wacht op medewerkers</span><strong>' + waiting.length + '</strong></div>',
      confirm: "Werkvoorraad sluiten",
      action: closeModal
    });
    toast(toastMessage + " De Backoffice-werkvoorraad is afgerond.");
    return;
  }
  const sameDossierTask = completedTask
    ? remaining.find(task => task.periodKey === completedTask.periodKey && Number(task.employee.id) === Number(completedTask.employee.id))
    : null;
  const previousIndex = previousOrder.indexOf(taskId);
  const nextFromPreviousOrder = previousOrder.slice(previousIndex + 1)
    .map(previousId => remaining.find(task => task.id === previousId))
    .find(Boolean);
  const nextTask = sameDossierTask || nextFromPreviousOrder || remaining[0];
  const remainingIds = previousOrder.filter(previousId => remaining.some(task => task.id === previousId));
  if (sameDossierTask) {
    const existingIndex = remainingIds.indexOf(sameDossierTask.id);
    if (existingIndex >= 0) remainingIds.splice(existingIndex, 1);
    const insertionIndex = previousIndex < 0 ? 0 : Math.min(previousIndex, remainingIds.length);
    remainingIds.splice(insertionIndex, 0, sameDossierTask.id);
  }
  remaining.forEach(task => {
    if (!remainingIds.includes(task.id)) remainingIds.push(task.id);
  });
  adminTaskWorkflow.taskIds = remainingIds;
  const opened = openAdminTask(nextTask.id, { continueWorkflow: true });
  if (!opened) {
    closeModal();
    toast(toastMessage + " De volgende Backoffice-actie kon niet veilig worden geopend.");
    return;
  }
  toast(toastMessage + " Volgende Backoffice-actie geopend.");
}

function openAdminTask(taskId, options = {}) {
  const task = actionableAdminTasks().find(item => item.id === taskId);
  if (!task) {
    toast("Deze Backoffice-actie staat niet meer open.");
    renderAll();
    return false;
  }
  const previousWorkflow = adminTaskWorkflow
    ? { taskIds: [...adminTaskWorkflow.taskIds], activeTaskId: adminTaskWorkflow.activeTaskId, completedCount: adminTaskWorkflow.completedCount }
    : null;
  if (!options.continueWorkflow || !adminTaskWorkflow) beginAdminTaskWorkflow(task.id);
  let opened = false;
  if (task.type === "hours-review") opened = showHoursReview(task.employee.id, task.periodKey, task.id);
  if (task.type === "customer-review") opened = showCustomerTimesheetDetails(task.employee.id, task.periodKey, true, task.id);
  if (task.type === "customer-broker") opened = showCustomerTimesheetBrokerCheck(task.employee.id, task.periodKey, task.id);
  if (task.type === "invoice-delivery") opened = showInvoiceDeliveryCheck(task.employee.id, task.periodKey, task.id);
  if (!opened) {
    adminTaskWorkflow = previousWorkflow;
    if (previousWorkflow && !document.querySelector("#modal").hidden) renderModalTaskNavigation(previousWorkflow.activeTaskId);
    else document.querySelector("#modal-queue").hidden = true;
    return false;
  }
  return true;
}

function renderDashboardNextAction(tasks) {
  const card = document.querySelector("#dashboard-next-action-card");
  if (!card) return;
  const actionable = tasks.filter(task => task.actionable);
  const waiting = tasks.filter(task => !task.actionable);
  const nextAction = actionable[0] || waiting[0] || null;
  const label = document.querySelector("#dashboard-next-action-label");
  const title = document.querySelector("#dashboard-next-action-title");
  const person = document.querySelector("#dashboard-next-action-person");
  const period = document.querySelector("#dashboard-next-action-period");
  const note = document.querySelector("#dashboard-next-action-note");
  const queue = document.querySelector("#dashboard-next-action-queue");
  const waitingNote = document.querySelector("#dashboard-next-action-waiting");
  const controls = document.querySelector("#dashboard-next-action-controls");
  card.classList.remove("is-actionable", "is-waiting", "is-complete");

  if (actionable.length) {
    card.classList.add("is-actionable");
    label.textContent = "Volgende actie · 1 van " + actionable.length + " bij Backoffice";
    title.textContent = nextAction.title;
    person.textContent = nextAction.employee.name;
    period.textContent = nextAction.period.label + " · " + nextAction.employee.client + " / " + nextAction.employee.broker;
    note.textContent = nextAction.note;
    queue.textContent = actionable.length === 1 ? "Dit is de laatste Backoffice-actie" : "Daarna nog " + (actionable.length - 1) + " bij Backoffice";
    waitingNote.textContent = waiting.length ? waiting.length + " " + (waiting.length === 1 ? "actie wacht" : "acties wachten") + " op medewerkers" : "Er wacht niets op medewerkers";
    controls.innerHTML = '<button class="button button-primary" id="dashboard-next-action-button" type="button" data-admin-task-id="' + nextAction.id + '">Start deze actie</button>';
    return;
  }

  if (waiting.length) {
    card.classList.add("is-waiting");
    label.textContent = "Voor jou is nu niets te doen";
    title.textContent = "Wacht op " + nextAction.employee.name + ": " + nextAction.title.toLowerCase();
    person.textContent = nextAction.employee.name;
    period.textContent = nextAction.period.label + " · " + nextAction.employee.client + " / " + nextAction.employee.broker;
    note.textContent = nextAction.note;
    queue.textContent = "Backoffice is voorlopig klaar";
    waitingNote.textContent = waiting.length + " " + (waiting.length === 1 ? "actie wacht" : "acties wachten") + " op medewerkers";
    controls.innerHTML = adminTaskAction(nextAction);
    return;
  }

  card.classList.add("is-complete");
  label.textContent = "Werkvoorraad afgerond";
  title.textContent = "Er staat geen actie meer open";
  person.textContent = "Backoffice";
  period.textContent = currentPeriod().label;
  note.textContent = "Alle uren, klanturenstaten en verzendcontroles zijn afgehandeld.";
  queue.textContent = "0 bij Backoffice";
  waitingNote.textContent = "0 bij medewerkers";
  controls.innerHTML = "";
}

function awaitingAdminWorkflowHydration() {
  return API_ENABLED && authRuntime.mode === "auth" && authRuntime.authenticated
    && state.currentRole === "admin" && !readApiRuntime.adminWorkflowHydrated
    && !isLocalResetAuthoritative();
}

// On a fresh load the locally persisted seed shows a task count that the first
// admin-workflow read then corrects (often downward). Rendering that provisional
// number as if it were final made the dashboard visibly jump a second or two
// after login. Until the first server sync lands, show a neutral loading state
// instead of a figure that is about to change.
function renderDashboardActionsLoading() {
  const admin = currentAdmin();
  const setText = (selector, value) => { const node = document.querySelector(selector); if (node) node.textContent = value; };
  const setHidden = (selector, hidden) => { const node = document.querySelector(selector); if (node) node.hidden = hidden; };
  setText("#admin-dashboard-greeting", greetingForNow() + ", " + (admin ? admin.name.split(/\s+/)[0] : "beheerder"));
  setText("#admin-attention-note", "De actuele werkvoorraad wordt opgehaald…");
  setText("#hero-backoffice-count", "–");
  setText("#hero-employee-count", "–");
  setHidden("#hero-owner-badges", true);
  setHidden("#dashboard-work-count", true);
  setHidden("#dashboard-backoffice-count", true);
  setHidden("#dashboard-employee-count", true);
  setText("#hero-task-total", "Werkvoorraad laden…");
  setText("#hero-task-months", "");
  setText("#hero-task-owners", "");
  setText("#metric-actions", "–");
  setText("#metric-actions-note", "De actuele werkvoorraad wordt opgehaald…");
  setText("#metric-actions-link", "Even geduld…");
  setText("#workflow-open-count", "Deze maand: werkvoorraad laden…");
  setText("#workflow-open-breakdown", "");
  const workQueueAction = document.querySelector("#open-work-queue");
  if (workQueueAction) workQueueAction.hidden = true;
  const card = document.querySelector("#dashboard-next-action-card");
  if (card) {
    card.classList.remove("is-actionable", "is-waiting", "is-complete");
    setText("#dashboard-next-action-label", "Werkvoorraad laden…");
    setText("#dashboard-next-action-title", "Even geduld, de actuele werkvoorraad wordt opgehaald");
    setText("#dashboard-next-action-person", "Backoffice");
    setText("#dashboard-next-action-period", currentPeriod().label);
    setText("#dashboard-next-action-note", "De teller kan nog kort wijzigen tot de serverstand is geladen.");
    setText("#dashboard-next-action-queue", "");
    setText("#dashboard-next-action-waiting", "");
    const controls = document.querySelector("#dashboard-next-action-controls");
    if (controls) controls.innerHTML = "";
  }
}

function renderDashboardActions() {
  if (awaitingAdminWorkflowHydration()) {
    renderDashboardActionsLoading();
    return;
  }
  const tasks = adminOpenTasks();
  const workCount = tasks.length;
  const actionableCount = tasks.filter(task => task.actionable).length;
  const waitingCount = workCount - actionableCount;
  const workMonths = new Set(tasks.map(task => task.periodKey)).size;
  const workDossiers = new Set(tasks.map(task => task.periodKey + ":" + task.employee.id)).size;
  const selectedTasks = tasks.filter(task => task.periodKey === currentPeriod().key);
  const selectedActionableCount = selectedTasks.filter(task => task.actionable).length;
  const selectedWaitingCount = selectedTasks.length - selectedActionableCount;
  const selectedCustomerCount = selectedTasks.filter(task => task.category === "Klanturenstaat").length;
  const admin = currentAdmin();
  document.querySelector("#admin-dashboard-greeting").textContent = greetingForNow() + ", " + (admin ? admin.name.split(/\s+/)[0] : "beheerder");
  document.querySelector("#admin-attention-note").textContent = workCount
    ? workCount + " open " + (workCount === 1 ? "actie" : "acties") + " in " + workDossiers + " " + (workDossiers === 1 ? "dossier" : "dossiers") + " over " + workMonths + " " + (workMonths === 1 ? "maand" : "maanden") + "."
    : "Er staat niets open: alle uren, klanturenstaten en verzendcontroles zijn afgerond.";
  document.querySelector("#hero-backoffice-count").textContent = String(actionableCount);
  document.querySelector("#hero-employee-count").textContent = String(waitingCount);
  document.querySelector("#hero-owner-badges").hidden = workCount === 0;
  const dashboardWorkBadge = document.querySelector("#dashboard-work-count");
  const dashboardBackofficeBadge = document.querySelector("#dashboard-backoffice-count");
  const dashboardEmployeeBadge = document.querySelector("#dashboard-employee-count");
  dashboardWorkBadge.hidden = workCount === 0;
  dashboardBackofficeBadge.hidden = actionableCount === 0;
  dashboardEmployeeBadge.hidden = waitingCount === 0;
  dashboardBackofficeBadge.textContent = String(actionableCount);
  dashboardEmployeeBadge.textContent = String(waitingCount);
  const dashboardBadgeLabel = workCount === 0
    ? "Geen open acties"
    : workCount + " open acties: " + actionableCount + " bij Backoffice, " + waitingCount + " wacht op medewerkers";
  dashboardWorkBadge.setAttribute("aria-label", dashboardBadgeLabel);
  dashboardWorkBadge.title = dashboardBadgeLabel;
  const workQueueAction = document.querySelector("#open-work-queue");
  workQueueAction.hidden = workCount === 0;
  workQueueAction.disabled = false;
  workQueueAction.textContent = "Bekijk alle " + workCount + " open " + (workCount === 1 ? "actie" : "acties");
  workQueueAction.dataset.openWorkFilter = "all";
  document.querySelector("#hero-task-total").textContent = workCount + " open " + (workCount === 1 ? "actie" : "acties");
  document.querySelector("#hero-task-months").textContent = workCount ? adminTaskMonthEquation(tasks) : "Alles afgerond";
  document.querySelector("#hero-task-owners").textContent = workCount ? "Backoffice " + actionableCount + " + wacht op medewerkers " + waitingCount + " = " + workCount : "Backoffice 0 + wacht op medewerkers 0 = 0";
  document.querySelector("#metric-actions").textContent = actionableCount;
  document.querySelector("#metric-actions-note").textContent = waitingCount ? waitingCount + " " + (waitingCount === 1 ? "actie wacht" : "acties wachten") + " op medewerkers" : "Niets wacht op medewerkers";
  document.querySelector("#metric-actions-link").textContent = workCount ? "Bekijk alle " + workCount + " acties" : "Alles afgerond";
  document.querySelector("#workflow-open-count").textContent = "Deze maand: " + selectedTasks.length + " open " + (selectedTasks.length === 1 ? "actie" : "acties");
  document.querySelector("#workflow-open-breakdown").textContent = selectedActionableCount + " bij Backoffice · " + selectedWaitingCount + " wacht op medewerkers · waarvan " + selectedCustomerCount + " klanturensta" + (selectedCustomerCount === 1 ? "at" : "ten");
  renderDashboardNextAction(tasks);
}

function recordHasPeriodActivity(record) {
  return totalEntries(record.entries) > 0 || Number(record.leave || 0) > 0 || Number(record.sick || 0) > 0 || record.timesheetStatus !== "draft" || record.invoiceStatus !== "concept" || record.payrollStatus !== "concept" || correctionHistoryFor(record).length > 0 || customerTimesheetFor(record).status !== "missing";
}

function latestActivePeriodKeyForRole(role = state.currentRole) {
  const roleKey = role || state.currentRole || "employee";
  const currentMonthKey = currentCalendarPeriodKey();
  let keys = Object.keys(state.records || {}).filter(key => parsePeriodKey(key));
  if (roleKey === "employee") {
    const employee = currentEmployee();
    if (!employee) return state.selectedPeriodKey;
    keys = keys.filter(key => key <= currentMonthKey && recordHasPeriodActivity(recordFor(employee.id, key)));
  } else {
    keys = keys.filter(key => activeEmployees().some(employee => recordHasPeriodActivity(recordFor(employee.id, key))));
  }
  return keys.sort((left, right) => right.localeCompare(left))[0] || state.selectedPeriodKey;
}

function resetHomeDashboardState(role = state.currentRole) {
  // Terugkeren naar het startscherm is gewone navigatie binnen dezelfde
  // sessie. Alleen een nieuwe login kiest opnieuw de actuele kalendermaand;
  // een maand die de gebruiker daarna bewust kiest blijft app-breed actief.
  state.invoiceFilter = "all";
  state.adminTaskFilter = "all";
  persistState();
  renderPeriodHeadings();
}

function openPeriodSummaries() {
  const currentMonthKey = currentCalendarPeriodKey();
  return Object.keys(state.records)
    .filter(key => parsePeriodKey(key) && key <= currentMonthKey)
    .sort((left, right) => left.localeCompare(right))
    .map(periodKey => {
      const items = activeEmployees()
        .filter(employee => !employee.startDate || employee.startDate.slice(0, 7) <= periodKey)
        .map(employee => ({ employee, record: recordFor(employee.id, periodKey) }));
      const periodHasActivity = periodKey === currentMonthKey || items.some(item => recordHasPeriodActivity(item.record));
      if (!periodHasActivity) return null;
      const drafts = items.filter(item => item.record.timesheetStatus === "draft").length;
      const corrections = items.filter(item => item.record.timesheetStatus === "correction").length;
      const approvals = items.filter(item => item.record.timesheetStatus === "submitted").length;
      const deliveries = items.filter(item => item.record.timesheetStatus === "approved" && (item.record.invoiceStatus === "ready" || item.record.payrollStatus === "ready")).length;
      const customerDocuments = items.filter(item => item.employee.customerTimesheetExpected !== false && (["missing", "draft", "received", "resubmit"].includes(customerTimesheetFor(item.record).status) || (customerTimesheetFor(item.record).status === "approved" && item.employee.customerTimesheetBrokerEnabled !== false))).length;
      if (drafts + corrections + approvals + deliveries + customerDocuments === 0) return null;
      const parts = [];
      if (drafts) parts.push(drafts + " urenregistratie" + (drafts === 1 ? "" : "s") + " niet ingediend");
      if (corrections) parts.push(corrections + " " + (corrections === 1 ? "correctie" : "correcties"));
      if (approvals) parts.push(approvals + " " + (approvals === 1 ? "goedkeuring" : "goedkeuringen"));
      if (deliveries) parts.push(deliveries + " " + (deliveries === 1 ? "verzending" : "verzendingen"));
      if (customerDocuments) parts.push(customerDocuments + " klanturensta" + (customerDocuments === 1 ? "at" : "ten") + " open");
      const timing = periodKey < currentMonthKey ? "Eerdere maand · nog niet afgerond" : periodKey === currentMonthKey ? "Huidige maand" : "Geplande maand";
      return { periodKey, period: periodFromKey(periodKey), isOverdue: periodKey < currentMonthKey, timing, openCount: drafts + corrections + approvals + deliveries + customerDocuments, parts, counts: { drafts, corrections, approvals, deliveries, customerDocuments } };
    })
    .filter(Boolean);
}

function setWorkflowStep(id, visualState) {
  const element = document.querySelector(id);
  element.classList.remove("is-done", "is-current");
  if (visualState) element.classList.add(visualState);
}

function renderCustomerTimesheetPanel() {
  const panel = document.querySelector("#customer-timesheet-upload-panel");
  if (!panel) return;
  panel.hidden = state.currentRole !== "employee";
  if (panel.hidden) return;
  const employee = currentEmployee();
  const period = currentPeriod();
  const record = recordFor(employee.id, period.key);
  const documentRecord = customerTimesheetFor(record);
  const baseStatus = customerTimesheetStatusLabels[documentRecord.status] || customerTimesheetStatusLabels.missing;
  const status = documentRecord.status === "received" ? ["Opgeslagen · wacht op controle", baseStatus[1]] : baseStatus;
  const periodInput = document.querySelector("#customer-timesheet-period");
  periodInput.value = period.key;
  syncPeriodControls("#customer-timesheet-month", "#customer-timesheet-year", period.key);
  document.querySelector("#customer-timesheet-status").className = "status-pill " + status[1];
  document.querySelector("#customer-timesheet-status").textContent = status[0];
  const mail = customerTimesheetSubmissionMail(employee, period.key);
  document.querySelector("#customer-timesheet-mail-route").textContent = "Van " + employee.name + " aan " + (state.settings.supportName || "Path Backoffice") + " · " + (state.settings.supportEmail || SUPPORT_EMAIL);
  document.querySelector("#customer-timesheet-subject").textContent = mail.subject;
  document.querySelector("#customer-timesheet-body").textContent = mail.body;
  const current = document.querySelector("#customer-timesheet-current");
  current.innerHTML = documentRecord.status === "skipped"
    ? '<div><div><strong>Als rechtstreeks gemaild geregistreerd</strong><small>' + escapeHtml(documentRecord.skippedReason || "De klanturenstaat is al rechtstreeks naar Path Backoffice gemaild.") + (documentRecord.skippedBy ? " · door " + escapeHtml(documentRecord.skippedBy) : "") + (documentRecord.skippedAt ? " · " + escapeHtml(documentRecord.skippedAt) : "") + '</small></div>' + customerTimesheetStatusPill(record) + '<button class="small-button" data-restore-customer-timesheet>Alsnog uploaden</button></div>'
    : documentRecord.fileName
      ? '<div><div><strong>' + escapeHtml(documentRecord.fileName) + '</strong><small>' + (documentRecord.isExample ? "Voorbeeldbestand · geen echt klantdocument" : "Opgeslagen " + escapeHtml(documentRecord.uploadedAt || "datum onbekend") + (documentRecord.mimeType === "application/pdf" && /\.(jpe?g|png)$/i.test(documentRecord.originalFileName || "") ? " · " + escapeHtml(documentRecord.originalFileName) + " omgezet naar PDF" : "")) + (documentRecord.status === "received" ? " · Backoffice heeft een melding in de app" : "") + (documentRecord.reviewNote ? " · " + escapeHtml(documentRecord.reviewNote) : "") + '</small></div><span class="status-pill ' + status[1] + '">' + escapeHtml(status[0]) + '</span>' + (documentRecord.fileData ? '<button class="small-button" data-view-customer-timesheet="' + employee.id + '" data-period-key="' + period.key + '">Klanturenstaat bekijken</button>' : '<span></span>') + '</div>'
      : '<div><div><strong>Nog geen klanturenstaat voor ' + escapeHtml(period.label) + '</strong><small>De urenregistratie kan wel gewoon worden ingevuld en ingediend.</small></div>' + customerTimesheetStatusPill(record) + '<span></span></div>';
  const locked = ["received", "approved", "sent", "sent_to_broker", "skipped"].includes(documentRecord.status);
  const saveButton = document.querySelector("#customer-timesheet-save-draft");
  const submitButton = document.querySelector("#customer-timesheet-submit");
  const skipButton = document.querySelector("#customer-timesheet-skip");
  document.querySelector("#customer-timesheet-edit-mail").disabled = locked;
  saveButton.textContent = ["draft", "resubmit"].includes(documentRecord.status) ? "Concept vervangen" : "Concept opslaan";
  submitButton.textContent = documentRecord.status === "draft" ? "Concept indienen bij Backoffice" : "Indienen bij Backoffice";
  skipButton.hidden = !customerTimesheetNeedsEmployeeAction(documentRecord.status) && documentRecord.status !== "skipped";
  skipButton.textContent = documentRecord.status === "skipped" ? "Alsnog uploaden" : "Al rechtstreeks gemaild";
  syncCustomerTimesheetUploadActions();
}

function syncCustomerTimesheetUploadActions() {
  const employee = currentEmployee();
  const periodKey = document.querySelector("#customer-timesheet-period").value || currentPeriod().key;
  const documentRecord = customerTimesheetFor(recordFor(employee.id, periodKey));
  const fileInput = document.querySelector("#customer-timesheet-file");
  const file = fileInput.files && fileInput.files[0];
  const sourceType = file ? customerTimesheetSourceType(file) : "";
  const fileReady = Boolean(file && sourceType && file.size <= 2 * 1024 * 1024);
  const existingDraft = documentRecord.status === "draft" && Boolean(documentRecord.fileName && documentRecord.fileData);
  const locked = ["received", "approved", "sent", "sent_to_broker", "skipped"].includes(documentRecord.status);
  const saveButton = document.querySelector("#customer-timesheet-save-draft");
  const submitButton = document.querySelector("#customer-timesheet-submit");
  const help = document.querySelector("#customer-timesheet-action-help");
  saveButton.disabled = locked || !fileReady;
  submitButton.disabled = locked || (!fileReady && !existingDraft);
  help.className = "customer-timesheet-action-help";
  if (documentRecord.status === "approved") {
    help.textContent = "Deze klanturenstaat is al goedgekeurd. Kies een andere maand om een nieuwe upload te testen.";
    help.classList.add("is-warning");
  } else if (documentRecord.status === "received") {
    help.textContent = "Deze klanturenstaat is ingediend en wacht op controle door Backoffice.";
    help.classList.add("is-warning");
  } else if (["sent", "sent_to_broker"].includes(documentRecord.status)) {
    help.textContent = "Deze klanturenstaat is al verwerkt via de brokerroute.";
    help.classList.add("is-warning");
  } else if (documentRecord.status === "skipped") {
    help.textContent = "Deze klanturenstaat staat geregistreerd als al rechtstreeks gemaild. Kies Alsnog uploaden om deze registratie terug te draaien.";
    help.classList.add("is-ready");
  } else if (file && !sourceType) {
    help.textContent = "Dit bestandstype is niet toegestaan. Kies een PDF, JPG of PNG.";
    help.classList.add("is-warning");
  } else if (file && file.size > 2 * 1024 * 1024) {
    help.textContent = "Dit bestand is groter dan 2 MB. Kies een kleiner bestand.";
    help.classList.add("is-warning");
  } else if (fileReady) {
    help.textContent = "Bestand gekozen. Je kunt het als concept opslaan of direct indienen bij Backoffice.";
    help.classList.add("is-ready");
  } else if (existingDraft) {
    help.textContent = "Je concept staat klaar. Je kunt het nu indienen of een nieuw bestand kiezen om het te vervangen.";
    help.classList.add("is-ready");
  } else if (documentRecord.status === "resubmit") {
    help.textContent = "Backoffice vraagt een nieuw document. Kies eerst de juiste PDF, JPG of PNG.";
    help.classList.add("is-warning");
  } else {
    help.textContent = "Kies eerst een PDF, JPG of PNG. Daarna worden de knoppen actief.";
  }
}

function renderCustomerTimesheetAdmin() {
  const list = document.querySelector("#customer-timesheet-admin-list");
  if (!list) return;
  const period = currentPeriod();
  document.querySelector("#customer-timesheet-admin-title").textContent = "Klanturenstaten · " + period.label;
  const rows = activeEmployees().filter(employee => employee.customerTimesheetExpected !== false).map(employee => ({ employee, record: recordFor(employee.id, period.key) }));
  const reviewCount = rows.filter(item => customerTimesheetFor(item.record).status === "received").length;
  const employeeCount = rows.filter(item => ["missing", "draft", "resubmit"].includes(customerTimesheetFor(item.record).status)).length;
  document.querySelector("#customer-timesheet-admin-summary").textContent = rows.length + " verwacht · " + reviewCount + " te controleren · " + employeeCount + " wacht op medewerker" + (employeeCount === 1 ? "" : "s");

  if (isCustomerTimesheetAdminApiMode()) {
    rows.forEach(item => refreshCustomerTimesheetReadApi(period.key, item.employee.id));
  }

  list.innerHTML = rows.map(({ employee, record }) => {
    const documentRecord = customerTimesheetFor(record);
    let action = '<button class="small-button" data-customer-timesheet-details="' + employee.id + '" data-period-key="' + period.key + '">Details</button>';
    if (documentRecord.status === "received") action = '<button class="small-button" data-review-customer-timesheet="' + employee.id + '" data-period-key="' + period.key + '">Controleren</button>';
    if (["missing", "draft", "resubmit"].includes(documentRecord.status)) action = '<button class="small-button" data-remind-customer-timesheet="' + employee.id + '" data-period-key="' + period.key + '">Herinnering sturen</button>';
    if (documentRecord.status === "approved" && employee.customerTimesheetBrokerEnabled !== false) action = '<button class="small-button" data-send-customer-timesheet="' + employee.id + '" data-period-key="' + period.key + '">Brokerroute controleren</button>';
    const route = employee.customerTimesheetBrokerEnabled === false ? "Geen brokerroute" : customerTimesheetBrokerEmail(employee);
    return '<article class="customer-timesheet-admin-row"><div class="customer-timesheet-admin-person"><strong>' + escapeHtml(employee.name) + '</strong><small>' + escapeHtml(employee.broker) + '</small></div><div class="customer-timesheet-admin-meta"><span><small>Deadline</small><strong>Werkdag ' + Number(employee.customerTimesheetDueWorkday || 5) + '</strong></span><span><small>Brokerroute</small><strong>' + escapeHtml(route) + '</strong></span></div><div class="customer-timesheet-admin-footer">' + customerTimesheetStatusPill(record) + '<div class="customer-timesheet-admin-row-actions">' + action + '</div></div></article>';
  }).join("") || '<div class="dashboard-action-empty">Voor deze maand worden geen klanturenstaten verwacht.</div>';
}

function showCustomerTimesheetDetails(employeeId, periodKey, reviewMode, adminTaskId = "") {
  const employee = employeeById(employeeId);
  const period = periodFromKey(periodKey);
  const record = recordFor(employeeId, period.key);
  const documentRecord = customerTimesheetFor(record);
  const status = customerTimesheetStatusLabels[documentRecord.status] || customerTimesheetStatusLabels.missing;
  const submissionMail = customerTimesheetSubmissionMail(employee, period.key);
  const brokerMail = customerTimesheetBrokerMail(employee, period.key);
  const route = employee.customerTimesheetBrokerEnabled === false
    ? "Geen brokerverzending ingesteld"
    : customerTimesheetBrokerEmail(employee) + " · alleen na goedkeuring";
  const skippedSummary = documentRecord.status === "skipped"
    ? '<div><span>Reden</span><strong>' + escapeHtml(documentRecord.skippedReason || "De klanturenstaat is al rechtstreeks naar Path Backoffice gemaild.") + '</strong></div><div><span>Geregistreerd door</span><strong>' + escapeHtml(documentRecord.skippedBy || employee.name) + '</strong></div><div><span>Geregistreerd op</span><strong>' + escapeHtml(documentRecord.skippedAt || "Datum onbekend") + '</strong></div>'
    : '';
  const submissionSummary = documentRecord.status === "skipped"
    ? ''
    : '<div class="customer-timesheet-submission-review"><span>Van ' + escapeHtml(employee.name) + ' aan ' + escapeHtml(state.settings.supportName || "Path Backoffice") + '</span><strong>' + escapeHtml(submissionMail.subject) + '</strong><pre>' + escapeHtml(submissionMail.body) + '</pre></div>';
  const summary = '<div><span>Status</span><strong>' + escapeHtml(status[0]) + '</strong></div><div><span>Bestand</span><strong>' + escapeHtml(documentRecord.fileName || (documentRecord.status === "skipped" ? "Niet via de app ontvangen" : "Nog niet ontvangen")) + '</strong></div>' + skippedSummary + (documentRecord.fileData ? '<div><span>Document controleren</span><button class="small-button" data-view-customer-timesheet="' + employee.id + '" data-period-key="' + period.key + '">Klanturenstaat bekijken</button></div>' : '') + submissionSummary + '<div><span>Deadline</span><strong>Werkdag ' + Number(employee.customerTimesheetDueWorkday || 5) + '</strong></div><div><span>Brokerroute na goedkeuring</span><strong>' + escapeHtml(route) + '</strong></div><div><span>Factuur zonder klanturenstaat</span><strong>' + (employee.invoiceWithoutCustomerTimesheetAllowed === false ? "Niet toegestaan" : "Toegestaan") + '</strong></div><div><span>Onderwerp naar broker</span><strong>' + escapeHtml(brokerMail.subject) + '</strong></div>';
  if (reviewMode && documentRecord.status === "received") {
    showModal({
      label: "Klanturenstaat controleren",
      title: employee.name + " · " + period.label,
      message: "Controleer de opgeslagen PDF van de klanturenstaat en de juiste periode. Een aangeleverde JPG of PNG is hierbij al naar PDF omgezet; Path maakt het brondocument niet zelf.",
      summary,
      confirm: "Goedkeuren",
      secondary: "Opnieuw uploaden vragen",
      adminTaskId,
      action: () => {
        const handleApproveSuccess = () => {
          const toastMessage = "De klanturenstaat van " + employee.name + " is goedgekeurd.";
          if (adminTaskId) {
            finishAdminTaskAndContinue(adminTaskId, () => {}, toastMessage);
            return;
          }
          persistState(); closeModal(); renderAll(); toast(toastMessage);
        };
        const approveNow = () => {
          if (isCustomerTimesheetApiMode()) {
            return writeCustomerTimesheetToApi("approve", {
              employeeId: employee.id,
              periodKey: period.key
            }).then(handleApproveSuccess);
          }
          const mutate = () => {
            documentRecord.status = "approved";
            const timestamp = correctionTimestamp();
            documentRecord.reviewedAt = timestamp.label;
            documentRecord.reviewedBy = currentAdmin().name;
            documentRecord.reviewNote = "";
            addNotification({ audience: "employee", type: "customer-timesheet", employeeId: employee.id, title: "Klanturenstaat goedgekeurd", message: "Je klanturenstaat voor " + period.label + " is gecontroleerd.", periodKey: period.key, view: "timesheet" }, true);
          };
          const toastMessage = "De klanturenstaat van " + employee.name + " is goedgekeurd.";
          if (adminTaskId) {
            finishAdminTaskAndContinue(adminTaskId, mutate, toastMessage);
            return;
          }
          mutate();
          persistState(); closeModal(); renderAll(); toast(toastMessage);
          return Promise.resolve();
        };
        if (isCustomerTimesheetApiMode()) {
          approveNow().catch(error => {
            const message = String(error && error.message || "Klanturenstaat goedkeuren mislukt op server.");
            if (/only submitted customer timesheet|alleen een ingediende klanturenstaat/i.test(message)) {
              refreshCustomerTimesheetReadApi(period.key, employee.id, true)
                .then(() => {
                  const refreshed = customerTimesheetFor(recordFor(employee.id, period.key));
                  if (refreshed.status === "approved") {
                    handleApproveSuccess();
                    return;
                  }
                  if (refreshed.status !== "received") throw error;
                  return approveNow();
                })
                .catch(retryError => {
                  toast(String(retryError && retryError.message || "De status is ondertussen gewijzigd. De actuele klanturenstaat wordt opnieuw geladen."));
                });
              return;
            }
            refreshCustomerTimesheetReadApi(period.key, employee.id, true);
            toast(message);
            console.warn("Klanturenstaat goedkeuren mislukt", error);
          });
          return;
        }
        approveNow();
      },
      secondaryAction: () => {
        if (isCustomerTimesheetApiMode()) {
          writeCustomerTimesheetToApi("request_resubmit", {
            employeeId: employee.id,
            periodKey: period.key,
            reviewNote: "Upload de juiste of definitieve klanturenstaat als PDF, JPG of PNG."
          }).then(() => {
            const toastMessage = "Er is in de app gevraagd om een nieuw bestand. Er is niets gemaild.";
            if (adminTaskId) {
              finishAdminTaskAndContinue(adminTaskId, () => {}, toastMessage);
              return;
            }
            persistState(); closeModal(); renderAll(); toast(toastMessage);
          }).catch(error => {
            refreshCustomerTimesheetReadApi(period.key, employee.id, true);
            toast("De status is ondertussen gewijzigd. De actuele klanturenstaat wordt opnieuw geladen.");
            console.warn("Opnieuw uploaden vragen mislukt", error);
          });
          return;
        }
        const mutate = () => {
          documentRecord.status = "resubmit";
          documentRecord.reviewNote = "Upload de juiste of definitieve klanturenstaat als PDF, JPG of PNG.";
          addNotification({ audience: "employee", type: "customer-timesheet", employeeId: employee.id, title: "Klanturenstaat opnieuw uploaden", message: "Upload voor " + period.label + " de juiste of definitieve klanturenstaat als PDF, JPG of PNG.", periodKey: period.key, view: "timesheet" }, true);
        };
        const toastMessage = "Er is in de app gevraagd om een nieuw bestand. Er is niets gemaild.";
        if (adminTaskId) {
          finishAdminTaskAndContinue(adminTaskId, mutate, toastMessage);
          return;
        }
        mutate();
        persistState(); closeModal(); renderAll(); toast(toastMessage);
      }
    });
    return true;
  }
  if (adminTaskId) return false;
  showModal({ label: "Klanturenstaat", title: employee.name + " · " + period.label, message: "Dit is een apart klantdocument en geen door de app gemaakte urenstaat.", summary, confirm: "Sluiten", action: closeModal });
  return true;
}

function remindCustomerTimesheet(employeeId, periodKey) {
  const employee = employeeById(employeeId);
  const record = recordFor(employeeId, periodKey);
  const documentRecord = customerTimesheetFor(record);
  const timestamp = correctionTimestamp();
  documentRecord.reminderCount += 1;
  documentRecord.lastReminderAt = timestamp.label;
  addNotification({ audience: "employee", type: "customer-timesheet-reminder", employeeId: employee.id, title: "Klanturenstaat ontbreekt", message: "Upload de officiële klanturenstaat als PDF, JPG of PNG voor " + periodFromKey(periodKey).label + ". Deze upload staat los van je urenregistratie.", periodKey, view: "timesheet" }, true);
  persistState(); renderAll(); toast("Herinnering in de app klaargezet voor " + employee.name + "; e-mailverzending is uitgeschakeld.");
}

function showSkipCustomerTimesheet() {
  const employee = currentEmployee();
  const period = currentPeriod();
  const documentRecord = customerTimesheetFor(recordFor(employee.id, period.key));
  if (!customerTimesheetNeedsEmployeeAction(documentRecord.status)) {
    toast("Deze klanturenstaat kan niet meer als rechtstreeks gemaild worden geregistreerd.");
    return;
  }
  const defaultReason = "De klanturenstaat is al rechtstreeks naar Path Backoffice gemaild.";
  showModal({
    label: "Klanturenstaat afronden",
    title: employee.name + " · " + period.label,
    message: "Gebruik dit alleen wanneer je de officiële klanturenstaat buiten de app rechtstreeks naar Backoffice hebt gemaild. Backoffice ziet deze registratie en de reden.",
    summary: '<div class="modal-form full"><label class="full">Reden<textarea id="customer-timesheet-skip-reason" rows="4">' + escapeHtml(defaultReason) + '</textarea></label><p class="form-help full">De klanturenstaat verdwijnt uit de open werkvoorraad, maar blijft met deze reden in de maanddetails staan.</p></div>',
    confirm: "Als al gemaild registreren",
    action: () => {
      const reasonInput = document.querySelector("#customer-timesheet-skip-reason");
      const reason = reasonInput.value.trim();
      if (!reason) {
        reasonInput.classList.add("is-invalid");
        toast("Vul een reden in.");
        return;
      }
      if (isCustomerTimesheetApiMode()) {
        writeCustomerTimesheetToApi("mark_skipped", {
          employeeId: employee.id,
          periodKey: period.key,
          reviewNote: reason
        }).then(() => {
          persistState(); closeModal(); renderAll(); toast("De klanturenstaat staat als rechtstreeks gemaild geregistreerd.");
        }).catch(error => {
          toast(String(error && error.message || "Registreren als rechtstreeks gemaild mislukt op server."));
        });
        return;
      }
      const timestamp = correctionTimestamp();
      documentRecord.status = "skipped";
      documentRecord.skippedReason = reason;
      documentRecord.skippedAt = timestamp.label;
      documentRecord.skippedBy = employee.name;
      documentRecord.reviewNote = "";
      addNotification({ audience: "admin", type: "customer-timesheet-skipped", employeeId: employee.id, title: "Klanturenstaat al rechtstreeks gemaild", message: employee.name + " heeft voor " + period.label + " geregistreerd: " + reason, periodKey: period.key, view: "dashboard" }, true);
      persistState(); closeModal(); renderAll(); toast("De klanturenstaat staat als rechtstreeks gemaild geregistreerd.");
    }
  });
}

function restoreSkippedCustomerTimesheet() {
  const employee = currentEmployee();
  const period = currentPeriod();
  const documentRecord = customerTimesheetFor(recordFor(employee.id, period.key));
  if (documentRecord.status !== "skipped") return;

  if (isCustomerTimesheetApiMode()) {
    writeCustomerTimesheetToApi("restore_missing", {
      employeeId: employee.id,
      periodKey: period.key
    }).then(() => {
      persistState(); renderAll(); toast("De registratie is teruggedraaid. Je kunt de klanturenstaat nu uploaden.");
    }).catch(error => {
      toast(String(error && error.message || "Herstellen naar missing mislukt op server."));
    });
    return;
  }

  documentRecord.status = documentRecord.fileName && documentRecord.fileData ? "draft" : "missing";
  documentRecord.skippedReason = "";
  documentRecord.skippedAt = "";
  documentRecord.skippedBy = "";
  persistState(); renderAll(); toast("De registratie is teruggedraaid. Je kunt de klanturenstaat nu uploaden.");
}

