function handleMonthDelivery() {
  const readiness = monthBatchReadiness(currentPeriod().key);
  const periodKey = currentPeriod().key;
  const periodRows = readiness.rows;
  if (readiness.state === "blocked") {
    if (readiness.blockers.length === 1) {
      const blocker = readiness.blockers[0];
      openMonthBatchBlocker(blocker.employeeId, blocker.periodKey);
      return;
    }
    const firstBlockerAction = document.querySelector("#month-batch-blockers [data-month-blocker-action]");
    const blockerPanel = document.querySelector("#month-batch-card");
    if (blockerPanel && typeof blockerPanel.scrollIntoView === "function") blockerPanel.scrollIntoView({ behavior: smoothScrollBehavior(), block: "center" });
    if (firstBlockerAction) firstBlockerAction.focus();
    toast("Bekijk de " + readiness.blockers.length + " blokkades en open per medewerker direct de juiste status.");
    return;
  }
  const approved = readiness.pendingRows;
  if (!approved.length) {
    toast("Er staat geen goedgekeurde maandverzending meer klaar.");
    return;
  }
  const allRoutes = approved.flatMap(item => deliveryRoutesFor(item.employee));
  const safeAddresses = [state.settings.sender, ...allRoutes.map(route => route.email)];
  if (!safeAddresses.every(isValidEmail)) {
    toast("Maandverzending geblokkeerd: controleer de e-mailadressen.");
    return;
  }
  const routeCounters = new Map();
  allRoutes.forEach(route => {
    const counter = routeCounters.get(route.id) || { name: route.name, messages: 0, invoices: 0 };
    counter.messages += 1;
    if (route.invoiceAttachment) counter.invoices += 1;
    routeCounters.set(route.id, counter);
  });
  const routeSummary = [...routeCounters.values()].map(counter => "<div><span>" + escapeHtml(counter.name) + "</span><strong>" + counter.messages + " bericht" + (counter.messages === 1 ? "" : "en") + " · " + counter.invoices + " met factuur</strong></div>").join("");
  const customerDocuments = periodRows.filter(item => item.employee.customerTimesheetExpected !== false).map(item => customerTimesheetFor(item.record));
  const customerReady = customerDocuments.filter(item => item.status === "approved").length;
  const customerMissing = customerDocuments.filter(item => ["missing", "draft", "resubmit"].includes(item.status)).length;
  const customerReceived = customerDocuments.filter(item => item.status === "received").length;
  showModal({
    label: "Eén knop · gescheiden routes",
    title: "Maandverzending voor " + currentPeriod().label + " controleren?",
    message: "Na één bevestiging controleert de app per medewerker een afzonderlijk factuurbericht voor iedere aangevinkte ontvanger, met naam, maand en daadwerkelijke goedgekeurde uren. De factuur gaat alleen mee waar Factuur meesturen is aangevinkt. Klanturenstaten blijven aparte, eerst te controleren PDF-routes. Er wordt geen CC of BCC gebruikt en " + (testMailRoutingSummary() ? "in TEST gaan de drie afzonderlijke berichten uitsluitend naar de vaste testontvanger." : "e-mailverzending is uitgeschakeld."),
    summary: routeSummary + "<div><span>Klanturenstaten</span><strong>" + customerReady + " klaar voor brokerroute · " + customerReceived + " te controleren · " + customerMissing + " ontbrekend/concept/opnieuw</strong></div>",
    confirm: "Controle afronden",
    action: () => {
      const serverDelivery = API_ENABLED && authRuntime.mode === "auth" && state.currentRole === "admin";
      if (serverDelivery) {
        // Auto-refresh invoice data so the user never has to manually re-open Facturen.
        refreshInvoicesReadApi(periodKey, true).catch(() => null).then(() => {
          const serverInvoices = approved.map(item => serverInvoiceFor(item.employee.id, periodKey)).filter(Boolean);
          if (serverInvoices.length !== approved.length) {
            toast("Niet alle serverfacturen zijn beschikbaar. Probeer opnieuw of open Facturen voor meer details.");
            return;
          }

          Promise.all(serverInvoices.map(invoice => finalizeInvoiceAndQueueToApi(invoice)))
          .then(deliveries => Promise.all([
            refreshEmailQueueReadApi(true),
            refreshInvoicesReadApi(periodKey, true)
          ]).catch(() => null).then(() => {
            syncInvoiceStatusesFromApi(periodKey);
            releaseLocalResetAuthorityAfterServerWrite();
            persistState();
            closeModal();
            renderAll();
            const totalMessages = deliveries.reduce((sum, delivery) => sum + Number(delivery && delivery.queued || 0), 0);
            const totalSent = deliveries.reduce((sum, delivery) => sum + Number(delivery && delivery.sent || 0), 0);
            const testDelivery = deliveries.length > 0 && deliveries.every(delivery => delivery && delivery.testDelivery === true);
            toast(testDelivery
              ? "Maandverzending afgerond: " + totalSent + " e-mails verzonden via de beveiligde TEST-aflevering."
              : "Maandverzending gecontroleerd (dry-run): " + totalMessages + " berichten klaargezet via serverqueue.");
          }))
          .catch(error => {
            toast(String(error && error.message || "Koppeling met mailqueue tijdelijk niet bereikbaar."));
          });
        });
        return;
      }

      approved.forEach(item => {
        item.record.invoiceStatus = "simulated";
        item.record.payrollStatus = "simulated";
      });
      persistState();
      closeModal();
      renderAll();
      toast("Maandverzending gecontroleerd (dry-run): afzonderlijke berichten per ontvanger klaargezet; geen SMTP-verzending.");
    }
  });
}

