function setPeriod(periodKey) {
  const parsed = parsePeriodKey(periodKey);
  if (!parsed || parsed.year < 1 || parsed.year > 9999) return false;
  const next = makePeriodKey(parsed.year, parsed.monthIndex);
  if (state.currentRole === "employee") {
    const maxEmployeePeriodKey = currentCalendarPeriodKey();
    if (next > maxEmployeePeriodKey) {
      toast("Medewerkers kunnen geen toekomstige maand openen. Beschikbaar tot en met " + periodFromKey(maxEmployeePeriodKey).label + ".");
      return false;
    }
  }
  if (next === state.selectedPeriodKey) {
    return true;
  }
  state.selectedPeriodKey = next;
  if (document.querySelector("#view-invoices")?.classList.contains("is-active")) state.invoiceDetailCollapsed = false;
  ensurePeriodRecords(next);
  state.invoiceFilter = "all";
  readApiRuntime.invoiceDocumentFilter = "all";
  readApiRuntime.invoicePage = 1;
  document.querySelectorAll("[data-invoice-filter]").forEach(button => button.classList.toggle("is-active", button.dataset.invoiceFilter === "all"));
  document.querySelectorAll("[data-invoice-document-filter]").forEach(button => button.classList.toggle("is-active", button.dataset.invoiceDocumentFilter === "all"));
  persistState();
  renderAll();
  if (isCustomerTimesheetApiMode() && state.currentRole === "employee") {
    const employee = currentEmployee();
    refreshCustomerTimesheetReadApi(next, employee.id, true)
      .then(data => {
        const stillSelected = state.currentRole === "employee"
          && Number(currentEmployee()?.id || 0) === Number(employee.id)
          && currentPeriod().key === next;
        if (!data || !stillSelected) return;
        renderCustomerTimesheetPanel();
        if (document.querySelector("#view-employee-dashboard")?.classList.contains("is-active")) {
          renderEmployeeDashboard();
        }
      })
      .catch(() => null);
  }
  toast("Periode gewijzigd naar " + currentPeriod().label + ".");
  return true;
}

function changePeriod(delta) {
  setPeriod(shiftPeriodKey(state.selectedPeriodKey, delta));
}

