document.querySelector("#modal-confirm").addEventListener("click", () => modalAction ? modalAction() : closeModal());
document.querySelector("#modal-queue-previous").addEventListener("click", () => moveAdminTaskWorkflow(-1));
document.querySelector("#modal-queue-next").addEventListener("click", () => moveAdminTaskWorkflow(1));
document.querySelector("#modal").addEventListener("click", event => { if (event.target.id === "modal") closeModal(); });
document.addEventListener("keydown", event => {
  if (event.key === "Escape") {
    closeLoginAccountPanels();
    if (!document.querySelector("#modal").hidden) {
      closeModal();
      return;
    }
    closeTopbarPopovers();
    closeMonthChoicePanels();
    closeReminderChoicePanels();
    closeStandardChoicePanels();
    closeHelp();
  }
  handleEnterSave(event);
});

window.addEventListener("scroll", () => {
  closeTopbarPopovers();
  // Choice panels stay anchored to their controls while scrolling. Closing them
  // here races with browsers that scroll an option into view before dispatching
  // its click, leaving the option hidden during actionability checks.
}, { passive: true });

initializeReminderChoiceMenus();
initializeStandardChoiceMenus();
populateSettings();
renderAll();
const passwordResetLinkActive = consumePasswordResetFragment();
initializeAuthSession().finally(() => {
  if (passwordResetLinkActive) showPasswordResetForm();
  restoreAuthLoginCountdown();
});
prefillAuthCredentialsFromSelection("admin", false);
